import type { CatalogDetails } from "@rpg/shared";

export const SRD51_DETAILS: Record<string, CatalogDetails> = {"srd:aboleth":{"pt-BR":{"lines":[{"label":"Deslocamento","text":"10 ft, natação 40 ft"},{"label":"Testes de resistência","text":"CON +6, INT +8, SAB +6"},{"label":"Perícias","text":"História +12, Percepção +10"},{"label":"Sentidos","text":"visão no escuro 120 ft, Percepção passiva 20"},{"label":"Idiomas","text":"Dialeto das Profundezas, telepatia 120 ft"}],"traits":[{"name":"Anfíbio","desc":"O aboleth pode respirar ar e água."},{"name":"Nuvem de Muco","desc":"Enquanto está submerso, o aboleth fica envolto num muco transformador. Uma criatura que toque o aboleth ou o acerte com um ataque corpo a corpo estando a até 5 ft dele deve fazer um teste de resistência de Constituição CD 14. Se falhar, a criatura fica doente por 1d4 horas. A criatura doente só consegue respirar debaixo d'água."},{"name":"Telepatia Investigativa","desc":"Se uma criatura se comunicar telepaticamente com o aboleth, o aboleth descobre os maiores desejos dela, se puder vê-la."}],"actions":[{"name":"Ataques Múltiplos","desc":"O aboleth faz três ataques de tentáculo."},{"name":"Escravizar (3/dia)","desc":"O aboleth escolhe uma criatura que possa ver a até 30 ft. O alvo deve passar num teste de resistência de Sabedoria CD 14 ou fica magicamente enfeitiçado pelo aboleth até o aboleth morrer ou até estarem em planos de existência diferentes. O alvo enfeitiçado fica sob o controle do aboleth, não pode usar reações, e os dois podem se comunicar telepaticamente a qualquer distância.\nSempre que sofrer dano, o alvo enfeitiçado pode repetir o teste de resistência; se passar, o efeito acaba. No máximo uma vez a cada 24 horas, o alvo também pode repetir o teste quando estiver a pelo menos 1,5 km do aboleth."}],"reactions":[],"legendary":[{"name":"Detectar","desc":"O aboleth faz um teste de Sabedoria (Percepção)."},{"name":"Golpe de Cauda","desc":"O aboleth faz um ataque de cauda."},{"name":"Dreno Psíquico (custa 2 ações)","desc":"Uma criatura enfeitiçada pelo aboleth sofre 10 (3d6) de dano psíquico, e o aboleth recupera pontos de vida iguais ao dano sofrido."}]},"en":{"lines":[{"label":"Speed","text":"10 ft, swim 40 ft"},{"label":"Saving Throws","text":"Con +6, Int +8, Wis +6"},{"label":"Skills","text":"History +12, Perception +10"},{"label":"Senses","text":"darkvision 120 ft, passive Perception 20"},{"label":"Languages","text":"Deep Speech, telepathy 120 ft."}],"traits":[{"name":"Amphibious","desc":"The aboleth can breathe air and water."},{"name":"Mucous Cloud","desc":"While underwater, the aboleth is surrounded by transformative mucus. A creature that touches the aboleth or that hits it with a melee attack while within 5 ft. of it must make a DC 14 Constitution saving throw. On a failure, the creature is diseased for 1d4 hours. The diseased creature can breathe only underwater."},{"name":"Probing Telepathy","desc":"If a creature communicates telepathically with the aboleth, the aboleth learns the creature's greatest desires if the aboleth can see the creature."}],"actions":[{"name":"Multiattack","desc":"The aboleth makes three tentacle attacks."},{"name":"Enslave (3/Day)","desc":"The aboleth targets one creature it can see within 30 ft. of it. The target must succeed on a DC 14 Wisdom saving throw or be magically charmed by the aboleth until the aboleth dies or until it is on a different plane of existence from the target. The charmed target is under the aboleth's control and can't take reactions, and the aboleth and the target can communicate telepathically with each other over any distance.\nWhenever the charmed target takes damage, the target can repeat the saving throw. On a success, the effect ends. No more than once every 24 hours, the target can also repeat the saving throw when it is at least 1 mile away from the aboleth."}],"reactions":[],"legendary":[{"name":"Detect","desc":"The aboleth makes a Wisdom (Perception) check."},{"name":"Tail Swipe","desc":"The aboleth makes one tail attack."},{"name":"Psychic Drain (Costs 2 Actions)","desc":"One creature charmed by the aboleth takes 10 (3d6) psychic damage, and the aboleth regains hit points equal to the damage the creature takes."}]},"es":{"lines":[{"label":"Velocidad","text":"10 ft, nadar 40 ft"},{"label":"Tiradas de salvación","text":"CON +6, INT +8, SAB +6"},{"label":"Habilidades","text":"Historia +12, Percepción +10"},{"label":"Sentidos","text":"visión en la oscuridad 120 ft, Percepción pasiva 20"},{"label":"Idiomas","text":"Habla profunda, telepatía 120 ft"}],"traits":[{"name":"Anfibio","desc":"El aboleth puede respirar aire y agua."},{"name":"Nube de mucosidad","desc":"Mientras está bajo el agua, el aboleth está rodeado de una mucosidad transformadora. Una criatura que toque al aboleth o lo golpee con un ataque cuerpo a cuerpo estando a 5 ft o menos de él debe hacer una tirada de salvación de Constitución CD 14. Si falla, la criatura enferma durante 1d4 horas. La criatura enferma solo puede respirar bajo el agua."},{"name":"Telepatía indagadora","desc":"Si una criatura se comunica telepáticamente con el aboleth, el aboleth descubre sus mayores deseos, si puede verla."}],"actions":[{"name":"Ataque múltiple","desc":"El aboleth hace tres ataques de tentáculo."},{"name":"Esclavizar (3/día)","desc":"El aboleth elige una criatura que pueda ver a 30 ft o menos. El objetivo debe superar una tirada de salvación de Sabiduría CD 14 o queda hechizado mágicamente por el aboleth hasta que el aboleth muera o hasta que estén en planos de existencia distintos. El objetivo hechizado queda bajo el control del aboleth, no puede usar reacciones, y ambos pueden comunicarse telepáticamente a cualquier distancia.\nCada vez que recibe daño, el objetivo hechizado puede repetir la tirada de salvación; si la supera, el efecto termina. Como mucho una vez cada 24 horas, el objetivo también puede repetirla cuando esté a 1,5 km o más del aboleth."}],"reactions":[],"legendary":[{"name":"Detectar","desc":"El aboleth hace una prueba de Sabiduría (Percepción)."},{"name":"Coletazo","desc":"El aboleth hace un ataque de cola."},{"name":"Drenaje psíquico (cuesta 2 acciones)","desc":"Una criatura hechizada por el aboleth recibe 10 (3d6) de daño psíquico, y el aboleth recupera tantos puntos de golpe como el daño recibido."}]}},"srd:acolyte":{"pt-BR":{"lines":[{"label":"Deslocamento","text":"30 ft"},{"label":"Perícias","text":"Medicina +4, Religião +2"},{"label":"Sentidos","text":"Percepção passiva 12"},{"label":"Idiomas","text":"um idioma qualquer (geralmente Comum)"}],"traits":[{"name":"Conjuração","desc":"O acólito é um conjurador de 1º nível. Sua habilidade de conjuração é Sabedoria (CD de resistência de magia 12, +4 para acertar com ataques de magia). O acólito tem as seguintes magias de clérigo preparadas:\n\n* Truques (à vontade): luz, chama sagrada, taumaturgia\n* 1º nível (3 espaços): bênção, curar ferimentos, santuário"}],"actions":[],"reactions":[],"legendary":[]},"en":{"lines":[{"label":"Speed","text":"30 ft"},{"label":"Skills","text":"Medicine +4, Religion +2"},{"label":"Senses","text":"passive Perception 12"},{"label":"Languages","text":"any one language (usually Common)"}],"traits":[{"name":"Spellcasting","desc":"The acolyte is a 1st-level spellcaster. Its spellcasting ability is Wisdom (spell save DC 12, +4 to hit with spell attacks). The acolyte has following cleric spells prepared:\n\n* Cantrips (at will): light, sacred flame, thaumaturgy\n* 1st level (3 slots): bless, cure wounds, sanctuary"}],"actions":[],"reactions":[],"legendary":[]},"es":{"lines":[{"label":"Velocidad","text":"30 ft"},{"label":"Habilidades","text":"Medicina +4, Religión +2"},{"label":"Sentidos","text":"Percepción pasiva 12"},{"label":"Idiomas","text":"un idioma cualquiera (normalmente común)"}],"traits":[{"name":"Lanzamiento de conjuros","desc":"El acólito es un lanzador de conjuros de nivel 1. Su aptitud mágica es Sabiduría (CD de salvación de conjuros 12, +4 al ataque con conjuros). El acólito tiene preparados los siguientes conjuros de clérigo:\n\n* Trucos (a voluntad): luz, llama sagrada, taumaturgia\n* Nivel 1 (3 espacios): bendición, curar heridas, santuario"}],"actions":[],"reactions":[],"legendary":[]}},"srd:air-elemental":{"pt-BR":{"lines":[{"label":"Deslocamento","text":"0 ft, voo 90 ft (pairar)"},{"label":"Resistência a dano","text":"elétrico, trovejante; concussão, perfurante e cortante de ataques não mágicos"},{"label":"Imunidade a dano","text":"veneno"},{"label":"Imunidade a condição","text":"exaustão, agarrado, paralisado, petrificado, envenenado, caído, impedido, inconsciente"},{"label":"Sentidos","text":"visão no escuro 60 ft, Percepção passiva 10"},{"label":"Idiomas","text":"Auran"}],"traits":[{"name":"Forma de Ar","desc":"O elemental pode entrar no espaço de uma criatura hostil e parar ali. Pode passar por um espaço de apenas 2,5 cm de largura sem se espremer."}],"actions":[{"name":"Ataques Múltiplos","desc":"O elemental faz dois ataques de pancada."},{"name":"Redemoinho","desc":"Cada criatura no espaço do elemental deve fazer um teste de resistência de Força CD 13. Se falhar, sofre 15 (3d8 + 2) de dano de concussão e é arremessada 20 ft para longe do elemental, numa direção aleatória, e cai. Se o alvo arremessado bater num objeto, como uma parede ou o chão, sofre 3 (1d6) de dano de concussão a cada 10 ft que voou. Se for arremessado contra outra criatura, essa criatura deve passar num teste de resistência de Destreza CD 13 ou sofre o mesmo dano e cai.\nSe passar no teste de resistência, o alvo sofre metade do dano de concussão e não é arremessado nem derrubado."}],"reactions":[],"legendary":[]},"en":{"lines":[{"label":"Speed","text":"0 ft, fly 90 ft (hover)"},{"label":"Damage Resistances","text":"lightning, thunder; bludgeoning, piercing, and slashing from nonmagical attacks"},{"label":"Damage Immunities","text":"poison"},{"label":"Condition Immunities","text":"exhaustion, grappled, paralyzed, petrified, poisoned, prone, restrained, unconscious"},{"label":"Senses","text":"darkvision 60 ft, passive Perception 10"},{"label":"Languages","text":"Auran"}],"traits":[{"name":"Air Form","desc":"The elemental can enter a hostile creature's space and stop there. It can move through a space as narrow as 1 inch wide without squeezing."}],"actions":[{"name":"Multiattack","desc":"The elemental makes two slam attacks."},{"name":"Whirlwind","desc":"Each creature in the elemental's space must make a DC 13 Strength saving throw. On a failure, a target takes 15 (3d8 + 2) bludgeoning damage and is flung up 20 feet away from the elemental in a random direction and knocked prone. If a thrown target strikes an object, such as a wall or floor, the target takes 3 (1d6) bludgeoning damage for every 10 feet it was thrown. If the target is thrown at another creature, that creature must succeed on a DC 13 Dexterity saving throw or take the same damage and be knocked prone.\nIf the saving throw is successful, the target takes half the bludgeoning damage and isn't flung away or knocked prone."}],"reactions":[],"legendary":[]},"es":{"lines":[{"label":"Velocidad","text":"0 ft, volar 90 ft (levitar)"},{"label":"Resistencias al daño","text":"relámpago, trueno; contundente, perforante y cortante de ataques no mágicos"},{"label":"Inmunidades al daño","text":"veneno"},{"label":"Inmunidades a estados","text":"agotamiento, agarrado, paralizado, petrificado, envenenado, derribado, apresado, inconsciente"},{"label":"Sentidos","text":"visión en la oscuridad 60 ft, Percepción pasiva 10"},{"label":"Idiomas","text":"Aurano"}],"traits":[{"name":"Forma de aire","desc":"El elemental puede entrar en el espacio de una criatura hostil y detenerse allí. Puede pasar por un espacio de solo 2,5 cm de ancho sin apretarse."}],"actions":[{"name":"Ataque múltiple","desc":"El elemental hace dos ataques de golpe."},{"name":"Torbellino","desc":"Cada criatura en el espacio del elemental debe hacer una tirada de salvación de Fuerza CD 13. Si falla, recibe 15 (3d8 + 2) de daño contundente, sale despedida 20 ft en una dirección aleatoria y queda derribada. Si el objetivo choca contra un objeto, como una pared o el suelo, recibe 3 (1d6) de daño contundente por cada 10 ft que haya volado. Si sale despedido contra otra criatura, esa criatura debe superar una tirada de salvación de Destreza CD 13 o recibe el mismo daño y queda derribada.\nSi supera la tirada de salvación, el objetivo recibe la mitad del daño contundente y no sale despedido ni queda derribado."}],"reactions":[],"legendary":[]}},"srd:androsphinx":{"pt-BR":{"lines":[{"label":"Deslocamento","text":"40 ft, voo 60 ft"},{"label":"Testes de resistência","text":"DES +6, CON +11, INT +9, SAB +10"},{"label":"Perícias","text":"Arcanismo +9, Percepção +10, Religião +15"},{"label":"Imunidade a dano","text":"psíquico; concussão, perfurante e cortante de ataques não mágicos"},{"label":"Imunidade a condição","text":"enfeitiçado, amedrontado"},{"label":"Sentidos","text":"visão verdadeira 120 ft, Percepção passiva 20"},{"label":"Idiomas","text":"Comum, Esfinge"}],"traits":[{"name":"Inescrutável","desc":"A esfinge é imune a qualquer efeito que perceba suas emoções ou leia seus pensamentos, e a qualquer magia de adivinhação que ela recuse. Testes de Sabedoria (Intuição) para descobrir as intenções ou a sinceridade da esfinge têm desvantagem."},{"name":"Armas Mágicas","desc":"Os ataques com arma da esfinge são mágicos."},{"name":"Conjuração","desc":"A esfinge é uma conjuradora de 12º nível. Sua habilidade de conjuração é Sabedoria (CD de resistência de magia 18, +10 para acertar com ataques de magia). Ela não precisa de componentes materiais para conjurar. A esfinge tem as seguintes magias de clérigo preparadas:\n\n* Truques (à vontade): chama sagrada, poupar os moribundos, taumaturgia\n* 1º nível (4 espaços): comando, detectar o bem e o mal, detectar magia\n* 2º nível (3 espaços): restauração menor, zona da verdade\n* 3º nível (3 espaços): dissipar magia, idiomas\n* 4º nível (3 espaços): banimento, liberdade de movimento\n* 5º nível (2 espaços): coluna de chamas, restauração maior\n* 6º nível (1 espaço): banquete de heróis"}],"actions":[{"name":"Ataques Múltiplos","desc":"A esfinge faz dois ataques de garra."},{"name":"Rugido (3/dia)","desc":"A esfinge solta um rugido mágico. A cada vez que ruge antes de terminar um descanso longo, o rugido é mais alto e o efeito muda, como abaixo. Cada criatura a até 500 ft da esfinge que possa ouvir o rugido deve fazer um teste de resistência.\n**Primeiro Rugido.** Cada criatura que falhar num teste de resistência de Sabedoria CD 18 fica amedrontada por 1 minuto. A criatura amedrontada pode repetir o teste ao fim de cada um dos seus turnos, encerrando o efeito em si mesma se passar.\n**Segundo Rugido.** Cada criatura que falhar num teste de resistência de Sabedoria CD 18 fica surda e amedrontada por 1 minuto. A criatura amedrontada fica paralisada e pode repetir o teste ao fim de cada um dos seus turnos, encerrando o efeito em si mesma se passar.\n**Terceiro Rugido.** Cada criatura faz um teste de resistência de Constituição CD 18. Se falhar, sofre 44 (8d10) de dano trovejante e cai. Se passar, sofre metade do dano e não cai."}],"reactions":[],"legendary":[{"name":"Ataque de Garra","desc":"A esfinge faz um ataque de garra."},{"name":"Teletransporte (custa 2 ações)","desc":"A esfinge se teletransporta magicamente, junto com o equipamento que veste ou carrega, até 120 ft para um espaço desocupado que possa ver."},{"name":"Conjurar uma Magia (custa 3 ações)","desc":"A esfinge conjura uma magia da sua lista de magias preparadas, gastando um espaço de magia normalmente."}]},"en":{"lines":[{"label":"Speed","text":"40 ft, fly 60 ft"},{"label":"Saving Throws","text":"Dex +6, Con +11, Int +9, Wis +10"},{"label":"Skills","text":"Arcana +9, Perception +10, Religion +15"},{"label":"Damage Immunities","text":"psychic; bludgeoning, piercing, and slashing from nonmagical attacks"},{"label":"Condition Immunities","text":"charmed, frightened"},{"label":"Senses","text":"truesight 120 ft, passive Perception 20"},{"label":"Languages","text":"Common, Sphinx"}],"traits":[{"name":"Inscrutable","desc":"The sphinx is immune to any effect that would sense its emotions or read its thoughts, as well as any divination spell that it refuses. Wisdom (Insight) checks made to ascertain the sphinx's intentions or sincerity have disadvantage."},{"name":"Magic Weapons","desc":"The sphinx's weapon attacks are magical."},{"name":"Spellcasting","desc":"The sphinx is a 12th-level spellcaster. Its spellcasting ability is Wisdom (spell save DC 18, +10 to hit with spell attacks). It requires no material components to cast its spells. The sphinx has the following cleric spells prepared:\n\n* Cantrips (at will): sacred flame, spare the dying, thaumaturgy\n* 1st level (4 slots): command, detect evil and good, detect magic\n* 2nd level (3 slots): lesser restoration, zone of truth\n* 3rd level (3 slots): dispel magic, tongues\n* 4th level (3 slots): banishment, freedom of movement\n* 5th level (2 slots): flame strike, greater restoration\n* 6th level (1 slot): heroes' feast"}],"actions":[{"name":"Multiattack","desc":"The sphinx makes two claw attacks."},{"name":"Roar (3/Day)","desc":"The sphinx emits a magical roar. Each time it roars before finishing a long rest, the roar is louder and the effect is different, as detailed below. Each creature within 500 feet of the sphinx and able to hear the roar must make a saving throw.\n**First Roar.** Each creature that fails a DC 18 Wisdom saving throw is frightened for 1 minute. A frightened creature can repeat the saving throw at the end of each of its turns, ending the effect on itself on a success.\n**Second Roar.** Each creature that fails a DC 18 Wisdom saving throw is deafened and frightened for 1 minute. A frightened creature is paralyzed and can repeat the saving throw at the end of each of its turns, ending the effect on itself on a success.\n**Third Roar.** Each creature makes a DC 18 Constitution saving throw. On a failed save, a creature takes 44 (8d10) thunder damage and is knocked prone. On a successful save, the creature takes half as much damage and isn't knocked prone."}],"reactions":[],"legendary":[{"name":"Claw Attack","desc":"The sphinx makes one claw attack."},{"name":"Teleport (Costs 2 Actions)","desc":"The sphinx magically teleports, along with any equipment it is wearing or carrying, up to 120 feet to an unoccupied space it can see."},{"name":"Cast a Spell (Costs 3 Actions)","desc":"The sphinx casts a spell from its list of prepared spells, using a spell slot as normal."}]},"es":{"lines":[{"label":"Velocidad","text":"40 ft, volar 60 ft"},{"label":"Tiradas de salvación","text":"DES +6, CON +11, INT +9, SAB +10"},{"label":"Habilidades","text":"Conocimiento arcano +9, Percepción +10, Religión +15"},{"label":"Inmunidades al daño","text":"psíquico; contundente, perforante y cortante de ataques no mágicos"},{"label":"Inmunidades a estados","text":"hechizado, asustado"},{"label":"Sentidos","text":"visión verdadera 120 ft, Percepción pasiva 20"},{"label":"Idiomas","text":"Común, esfinge"}],"traits":[{"name":"Inescrutable","desc":"La esfinge es inmune a cualquier efecto que perciba sus emociones o lea sus pensamientos, y a cualquier conjuro de adivinación que rechace. Las pruebas de Sabiduría (Perspicacia) para averiguar sus intenciones o su sinceridad tienen desventaja."},{"name":"Armas mágicas","desc":"Los ataques con arma de la esfinge son mágicos."},{"name":"Lanzamiento de conjuros","desc":"La esfinge es una lanzadora de conjuros de nivel 12. Su aptitud mágica es Sabiduría (CD de salvación de conjuros 18, +10 al ataque con conjuros). No necesita componentes materiales para lanzar sus conjuros. La esfinge tiene preparados los siguientes conjuros de clérigo:\n\n* Trucos (a voluntad): llama sagrada, piedad con los moribundos, taumaturgia\n* Nivel 1 (4 espacios): orden imperiosa, detectar el bien y el mal, detectar magia\n* Nivel 2 (3 espacios): restablecimiento menor, zona de verdad\n* Nivel 3 (3 espacios): disipar magia, don de lenguas\n* Nivel 4 (3 espacios): destierro, libertad de movimiento\n* Nivel 5 (2 espacios): descarga flamígera, restablecimiento mayor\n* Nivel 6 (1 espacio): banquete de héroes"}],"actions":[{"name":"Ataque múltiple","desc":"La esfinge hace dos ataques de garra."},{"name":"Rugido (3/día)","desc":"La esfinge emite un rugido mágico. Cada vez que ruge antes de terminar un descanso largo, el rugido es más fuerte y el efecto cambia, como se detalla abajo. Cada criatura a 500 ft o menos de la esfinge que pueda oír el rugido debe hacer una tirada de salvación.\n**Primer rugido.** Cada criatura que falle una tirada de salvación de Sabiduría CD 18 queda asustada durante 1 minuto. La criatura asustada puede repetir la tirada al final de cada uno de sus turnos y termina el efecto sobre sí misma si la supera.\n**Segundo rugido.** Cada criatura que falle una tirada de salvación de Sabiduría CD 18 queda ensordecida y asustada durante 1 minuto. La criatura asustada queda paralizada y puede repetir la tirada al final de cada uno de sus turnos, terminando el efecto sobre sí misma si la supera.\n**Tercer rugido.** Cada criatura hace una tirada de salvación de Constitución CD 18. Si falla, recibe 44 (8d10) de daño de trueno y queda derribada. Si la supera, recibe la mitad del daño y no queda derribada."}],"reactions":[],"legendary":[{"name":"Ataque de garra","desc":"La esfinge hace un ataque de garra."},{"name":"Teletransporte (cuesta 2 acciones)","desc":"La esfinge se teletransporta mágicamente, junto con el equipo que lleve puesto o encima, hasta 120 ft a un espacio desocupado que pueda ver."},{"name":"Lanzar un conjuro (cuesta 3 acciones)","desc":"La esfinge lanza un conjuro de su lista de conjuros preparados, gastando un espacio de conjuro de la forma habitual."}]}},"srd:animated-armor":{"pt-BR":{"lines":[{"label":"Deslocamento","text":"25 ft"},{"label":"Imunidade a dano","text":"veneno, psíquico"},{"label":"Imunidade a condição","text":"cego, enfeitiçado, surdo, exaustão, amedrontado, paralisado, petrificado, envenenado"},{"label":"Sentidos","text":"percepção às cegas 60 ft, Percepção passiva 6"}],"traits":[{"name":"Suscetível à Antimagia","desc":"A armadura fica incapacitada enquanto estiver na área de um campo antimagia. Se for alvo de dissipar magia, deve passar num teste de resistência de Constituição contra a CD de resistência de magia do conjurador ou fica inconsciente por 1 minuto."},{"name":"Falsa Aparência","desc":"Enquanto fica imóvel, a armadura é indistinguível de uma armadura comum."}],"actions":[{"name":"Ataques Múltiplos","desc":"A armadura faz dois ataques corpo a corpo."}],"reactions":[],"legendary":[]},"en":{"lines":[{"label":"Speed","text":"25 ft"},{"label":"Damage Immunities","text":"poison, psychic"},{"label":"Condition Immunities","text":"blinded, charmed, deafened, exhaustion, frightened, paralyzed, petrified, poisoned"},{"label":"Senses","text":"blindsight 60 ft, passive Perception 6"}],"traits":[{"name":"Antimagic Susceptibility","desc":"The armor is incapacitated while in the area of an antimagic field. If targeted by dispel magic, the armor must succeed on a Constitution saving throw against the caster's spell save DC or fall unconscious for 1 minute."},{"name":"False Appearance","desc":"While the armor remains motionless, it is indistinguishable from a normal suit of armor."}],"actions":[{"name":"Multiattack","desc":"The armor makes two melee attacks."}],"reactions":[],"legendary":[]},"es":{"lines":[{"label":"Velocidad","text":"25 ft"},{"label":"Inmunidades al daño","text":"veneno, psíquico"},{"label":"Inmunidades a estados","text":"cegado, hechizado, ensordecido, agotamiento, asustado, paralizado, petrificado, envenenado"},{"label":"Sentidos","text":"vista ciega 60 ft, Percepción pasiva 6"}],"traits":[{"name":"Susceptibilidad a la antimagia","desc":"La armadura queda incapacitada mientras esté en el área de un campo antimagia. Si es objetivo de disipar magia, debe superar una tirada de salvación de Constitución contra la CD de salvación de conjuros del lanzador o queda inconsciente durante 1 minuto."},{"name":"Apariencia falsa","desc":"Mientras permanece inmóvil, la armadura es indistinguible de una armadura normal."}],"actions":[{"name":"Ataque múltiple","desc":"La armadura hace dos ataques cuerpo a cuerpo."}],"reactions":[],"legendary":[]}},"srd:ankheg":{"pt-BR":{"lines":[{"label":"Deslocamento","text":"30 ft, escavação 10 ft"},{"label":"Sentidos","text":"visão no escuro 60 ft, sentido sísmico 60 ft, Percepção passiva 11"}],"traits":[],"actions":[{"name":"Jato de Ácido","desc":"O ankheg cospe ácido numa linha de 30 ft de comprimento por 5 ft de largura, desde que não esteja agarrando nenhuma criatura. Cada criatura na linha deve fazer um teste de resistência de Destreza CD 13; sofre 10 (3d6) de dano de ácido se falhar, ou metade se passar."}],"reactions":[],"legendary":[]},"en":{"lines":[{"label":"Speed","text":"30 ft, burrow 10 ft"},{"label":"Senses","text":"darkvision 60 ft, tremorsense 60 ft, passive Perception 11"}],"traits":[],"actions":[{"name":"Acid Spray","desc":"The ankheg spits acid in a line that is 30 ft. long and 5 ft. wide, provided that it has no creature grappled. Each creature in that line must make a DC 13 Dexterity saving throw, taking 10 (3d6) acid damage on a failed save, or half as much damage on a successful one."}],"reactions":[],"legendary":[]},"es":{"lines":[{"label":"Velocidad","text":"30 ft, excavar 10 ft"},{"label":"Sentidos","text":"visión en la oscuridad 60 ft, sentido de la vibración 60 ft, Percepción pasiva 11"}],"traits":[],"actions":[{"name":"Rociada de ácido","desc":"El ankheg escupe ácido en una línea de 30 ft de largo y 5 ft de ancho, siempre que no tenga a ninguna criatura agarrada. Cada criatura en la línea debe hacer una tirada de salvación de Destreza CD 13; recibe 10 (3d6) de daño de ácido si falla, o la mitad si la supera."}],"reactions":[],"legendary":[]}},"srd:ape":{"pt-BR":{"lines":[{"label":"Deslocamento","text":"30 ft, escalada 30 ft"},{"label":"Perícias","text":"Atletismo +5, Percepção +3"},{"label":"Sentidos","text":"Percepção passiva 13"}],"traits":[],"actions":[{"name":"Ataques Múltiplos","desc":"O macaco faz dois ataques de punho."}],"reactions":[],"legendary":[]},"en":{"lines":[{"label":"Speed","text":"30 ft, climb 30 ft"},{"label":"Skills","text":"Athletics +5, Perception +3"},{"label":"Senses","text":"passive Perception 13"}],"traits":[],"actions":[{"name":"Multiattack","desc":"The ape makes two fist attacks."}],"reactions":[],"legendary":[]},"es":{"lines":[{"label":"Velocidad","text":"30 ft, trepar 30 ft"},{"label":"Habilidades","text":"Atletismo +5, Percepción +3"},{"label":"Sentidos","text":"Percepción pasiva 13"}],"traits":[],"actions":[{"name":"Ataque múltiple","desc":"El simio hace dos ataques de puño."}],"reactions":[],"legendary":[]}},"srd:archmage":{"pt-BR":{"lines":[{"label":"Deslocamento","text":"30 ft"},{"label":"Testes de resistência","text":"INT +9, SAB +6"},{"label":"Perícias","text":"Arcanismo +13, História +13"},{"label":"Resistência a dano","text":"dano de magias; concussão, perfurante e cortante não mágicos (de pele de pedra)"},{"label":"Sentidos","text":"Percepção passiva 12"},{"label":"Idiomas","text":"seis idiomas quaisquer"}],"traits":[{"name":"Resistência à Magia","desc":"O arquimago tem vantagem em testes de resistência contra magias e outros efeitos mágicos."},{"name":"Conjuração","desc":"O arquimago é um conjurador de 18º nível. Sua habilidade de conjuração é Inteligência (CD de resistência de magia 17, +9 para acertar com ataques de magia). O arquimago pode conjurar disfarçar-se e invisibilidade à vontade e tem as seguintes magias de mago preparadas:\n\n* Truques (à vontade): raio de fogo, luz, mão mágica, prestidigitação, toque chocante\n* 1º nível (4 espaços): detectar magia, identificação, armadura arcana*, mísseis mágicos\n* 2º nível (3 espaços): detectar pensamentos, imagem espelhada, passo nebuloso\n* 3º nível (3 espaços): contramágica, voo, relâmpago\n* 4º nível (3 espaços): banimento, escudo de fogo, pele de pedra*\n* 5º nível (3 espaços): cone de frio, vidência, muralha de energia\n* 6º nível (1 espaço): globo de invulnerabilidade\n* 7º nível (1 espaço): teletransporte\n* 8º nível (1 espaço): mente em branco*\n* 9º nível (1 espaço): parar o tempo\n* O arquimago conjura essas magias em si mesmo antes do combate."}],"actions":[],"reactions":[],"legendary":[]},"en":{"lines":[{"label":"Speed","text":"30 ft"},{"label":"Saving Throws","text":"Int +9, Wis +6"},{"label":"Skills","text":"Arcana +13, History +13"},{"label":"Damage Resistances","text":"damage from spells; non magical bludgeoning, piercing, and slashing (from stoneskin)"},{"label":"Senses","text":"passive Perception 12"},{"label":"Languages","text":"any six languages"}],"traits":[{"name":"Magic Resistance","desc":"The archmage has advantage on saving throws against spells and other magical effects."},{"name":"Spellcasting","desc":"The archmage is an 18th-level spellcaster. Its spellcasting ability is Intelligence (spell save DC 17, +9 to hit with spell attacks). The archmage can cast disguise self and invisibility at will and has the following wizard spells prepared:\n\n* Cantrips (at will): fire bolt, light, mage hand, prestidigitation, shocking grasp\n* 1st level (4 slots): detect magic, identify, mage armor*, magic missile\n* 2nd level (3 slots): detect thoughts, mirror image, misty step\n* 3rd level (3 slots): counterspell,fly, lightning bolt\n* 4th level (3 slots): banishment, fire shield, stoneskin*\n* 5th level (3 slots): cone of cold, scrying, wall of force\n* 6th level (1 slot): globe of invulnerability\n* 7th level (1 slot): teleport\n* 8th level (1 slot): mind blank*\n* 9th level (1 slot): time stop\n* The archmage casts these spells on itself before combat."}],"actions":[],"reactions":[],"legendary":[]},"es":{"lines":[{"label":"Velocidad","text":"30 ft"},{"label":"Tiradas de salvación","text":"INT +9, SAB +6"},{"label":"Habilidades","text":"Conocimiento arcano +13, Historia +13"},{"label":"Resistencias al daño","text":"daño de conjuros; contundente, perforante y cortante no mágicos (de piel pétrea)"},{"label":"Sentidos","text":"Percepción pasiva 12"},{"label":"Idiomas","text":"seis idiomas cualesquiera"}],"traits":[{"name":"Resistencia mágica","desc":"El archimago tiene ventaja en las tiradas de salvación contra conjuros y otros efectos mágicos."},{"name":"Lanzamiento de conjuros","desc":"El archimago es un lanzador de conjuros de nivel 18. Su aptitud mágica es Inteligencia (CD de salvación de conjuros 17, +9 al ataque con conjuros). El archimago puede lanzar disfrazarse e invisibilidad a voluntad y tiene preparados los siguientes conjuros de mago:\n\n* Trucos (a voluntad): descarga de fuego, luz, mano de mago, prestidigitación, agarre electrizante\n* Nivel 1 (4 espacios): detectar magia, identificar, armadura de mago*, proyectil mágico\n* Nivel 2 (3 espacios): detectar pensamientos, imagen múltiple, paso brumoso\n* Nivel 3 (3 espacios): contraconjuro, volar, relámpago\n* Nivel 4 (3 espacios): destierro, escudo de fuego, piel pétrea*\n* Nivel 5 (3 espacios): cono de frío, escudriñar, muro de fuerza\n* Nivel 6 (1 espacio): globo de invulnerabilidad\n* Nivel 7 (1 espacio): teletransporte\n* Nivel 8 (1 espacio): mente en blanco*\n* Nivel 9 (1 espacio): detener el tiempo\n* El archimago lanza estos conjuros sobre sí mismo antes del combate."}],"actions":[],"reactions":[],"legendary":[]}},"srd:assassin":{"pt-BR":{"lines":[{"label":"Deslocamento","text":"30 ft"},{"label":"Testes de resistência","text":"DES +6, INT +4"},{"label":"Perícias","text":"Acrobacia +6, Enganação +3, Percepção +3, Furtividade +9"},{"label":"Resistência a dano","text":"veneno"},{"label":"Sentidos","text":"Percepção passiva 13"},{"label":"Idiomas","text":"gíria de ladrão e mais dois idiomas quaisquer"}],"traits":[{"name":"Assassinar","desc":"No seu primeiro turno, o assassino tem vantagem nas jogadas de ataque contra qualquer criatura que ainda não tenha jogado. Todo acerto do assassino contra uma criatura surpresa é um acerto crítico."},{"name":"Evasão","desc":"Se o assassino for alvo de um efeito que permita um teste de resistência de Destreza para sofrer só metade do dano, ele não sofre dano nenhum se passar, e só metade se falhar."},{"name":"Ataque Furtivo (1/turno)","desc":"O assassino causa 13 (4d6) de dano extra ao acertar um alvo com um ataque com arma tendo vantagem na jogada de ataque, ou quando o alvo estiver a até 5 ft de um aliado do assassino que não esteja incapacitado e o assassino não tiver desvantagem na jogada."}],"actions":[{"name":"Ataques Múltiplos","desc":"O assassino faz dois ataques de espada curta."}],"reactions":[],"legendary":[]},"en":{"lines":[{"label":"Speed","text":"30 ft"},{"label":"Saving Throws","text":"Dex +6, Int +4"},{"label":"Skills","text":"Acrobatics +6, Deception +3, Perception +3, Stealth +9"},{"label":"Damage Resistances","text":"poison"},{"label":"Senses","text":"passive Perception 13"},{"label":"Languages","text":"Thieves' cant plus any two languages"}],"traits":[{"name":"Assassinate","desc":"During its first turn, the assassin has advantage on attack rolls against any creature that hasn't taken a turn. Any hit the assassin scores against a surprised creature is a critical hit."},{"name":"Evasion","desc":"If the assassin is subjected to an effect that allows it to make a Dexterity saving throw to take only half damage, the assassin instead takes no damage if it succeeds on the saving throw, and only half damage if it fails."},{"name":"Sneak Attack (1/Turn)","desc":"The assassin deals an extra 13 (4d6) damage when it hits a target with a weapon attack and has advantage on the attack roll, or when the target is within 5 ft. of an ally of the assassin that isn't incapacitated and the assassin doesn't have disadvantage on the attack roll."}],"actions":[{"name":"Multiattack","desc":"The assassin makes two shortsword attacks."}],"reactions":[],"legendary":[]},"es":{"lines":[{"label":"Velocidad","text":"30 ft"},{"label":"Tiradas de salvación","text":"DES +6, INT +4"},{"label":"Habilidades","text":"Acrobacias +6, Engaño +3, Percepción +3, Sigilo +9"},{"label":"Resistencias al daño","text":"veneno"},{"label":"Sentidos","text":"Percepción pasiva 13"},{"label":"Idiomas","text":"jerga de ladrones y otros dos idiomas cualesquiera"}],"traits":[{"name":"Asesinar","desc":"Durante su primer turno, el asesino tiene ventaja en las tiradas de ataque contra cualquier criatura que todavía no haya tenido su turno. Cualquier impacto del asesino contra una criatura sorprendida es un crítico."},{"name":"Evasión","desc":"Si el asesino queda expuesto a un efecto que le permite una tirada de salvación de Destreza para recibir solo la mitad del daño, no recibe daño si la supera y solo la mitad si la falla."},{"name":"Ataque furtivo (1/turno)","desc":"El asesino inflige 13 (4d6) de daño adicional cuando impacta a un objetivo con un ataque con arma teniendo ventaja en la tirada, o cuando el objetivo está a 5 ft o menos de un aliado del asesino que no está incapacitado y el asesino no tiene desventaja en la tirada."}],"actions":[{"name":"Ataque múltiple","desc":"El asesino hace dos ataques de espada corta."}],"reactions":[],"legendary":[]}},"srd:awakened-shrub":{"pt-BR":{"lines":[{"label":"Deslocamento","text":"20 ft"},{"label":"Vulnerabilidade a dano","text":"fogo"},{"label":"Resistência a dano","text":"perfurante"},{"label":"Sentidos","text":"Percepção passiva 10"},{"label":"Idiomas","text":"um idioma que seu criador conheça"}],"traits":[{"name":"Falsa Aparência","desc":"Enquanto fica imóvel, o arbusto é indistinguível de um arbusto comum."}],"actions":[],"reactions":[],"legendary":[]},"en":{"lines":[{"label":"Speed","text":"20 ft"},{"label":"Damage Vulnerabilities","text":"fire"},{"label":"Damage Resistances","text":"piercing"},{"label":"Senses","text":"passive Perception 10"},{"label":"Languages","text":"one language known by its creator"}],"traits":[{"name":"False Appearance","desc":"While the shrub remains motionless, it is indistinguishable from a normal shrub."}],"actions":[],"reactions":[],"legendary":[]},"es":{"lines":[{"label":"Velocidad","text":"20 ft"},{"label":"Vulnerabilidades al daño","text":"fuego"},{"label":"Resistencias al daño","text":"perforante"},{"label":"Sentidos","text":"Percepción pasiva 10"},{"label":"Idiomas","text":"un idioma que conozca su creador"}],"traits":[{"name":"Apariencia falsa","desc":"Mientras permanece inmóvil, el arbusto es indistinguible de un arbusto normal."}],"actions":[],"reactions":[],"legendary":[]}},"srd:awakened-tree":{"pt-BR":{"lines":[{"label":"Deslocamento","text":"20 ft"},{"label":"Vulnerabilidade a dano","text":"fogo"},{"label":"Resistência a dano","text":"concussão, perfurante"},{"label":"Sentidos","text":"Percepção passiva 10"},{"label":"Idiomas","text":"um idioma que seu criador conheça"}],"traits":[{"name":"Falsa Aparência","desc":"Enquanto fica imóvel, a árvore é indistinguível de uma árvore comum."}],"actions":[],"reactions":[],"legendary":[]},"en":{"lines":[{"label":"Speed","text":"20 ft"},{"label":"Damage Vulnerabilities","text":"fire"},{"label":"Damage Resistances","text":"bludgeoning, piercing"},{"label":"Senses","text":"passive Perception 10"},{"label":"Languages","text":"one language known by its creator"}],"traits":[{"name":"False Appearance","desc":"While the tree remains motionless, it is indistinguishable from a normal tree."}],"actions":[],"reactions":[],"legendary":[]},"es":{"lines":[{"label":"Velocidad","text":"20 ft"},{"label":"Vulnerabilidades al daño","text":"fuego"},{"label":"Resistencias al daño","text":"contundente, perforante"},{"label":"Sentidos","text":"Percepción pasiva 10"},{"label":"Idiomas","text":"un idioma que conozca su creador"}],"traits":[{"name":"Apariencia falsa","desc":"Mientras permanece inmóvil, el árbol es indistinguible de un árbol normal."}],"actions":[],"reactions":[],"legendary":[]}},"srd:axe-beak":{"pt-BR":{"lines":[{"label":"Deslocamento","text":"50 ft"},{"label":"Sentidos","text":"Percepção passiva 10"}],"traits":[],"actions":[],"reactions":[],"legendary":[]},"en":{"lines":[{"label":"Speed","text":"50 ft"},{"label":"Senses","text":"passive Perception 10"}],"traits":[],"actions":[],"reactions":[],"legendary":[]},"es":{"lines":[{"label":"Velocidad","text":"50 ft"},{"label":"Sentidos","text":"Percepción pasiva 10"}],"traits":[],"actions":[],"reactions":[],"legendary":[]}},"srd:azer":{"pt-BR":{"lines":[{"label":"Deslocamento","text":"30 ft"},{"label":"Testes de resistência","text":"CON +4"},{"label":"Imunidade a dano","text":"fogo, veneno"},{"label":"Imunidade a condição","text":"envenenado"},{"label":"Sentidos","text":"Percepção passiva 11"},{"label":"Idiomas","text":"Ignan"}],"traits":[{"name":"Corpo Incandescente","desc":"Uma criatura que toque o azer ou o acerte com um ataque corpo a corpo estando a até 5 ft dele sofre 5 (1d10) de dano de fogo."},{"name":"Armas Incandescentes","desc":"Quando o azer acerta com uma arma corpo a corpo de metal, causa 3 (1d6) de dano de fogo extra (já incluído no ataque)."},{"name":"Iluminação","desc":"O azer emite luz plena num raio de 10 ft e penumbra por mais 10 ft."}],"actions":[],"reactions":[],"legendary":[]},"en":{"lines":[{"label":"Speed","text":"30 ft"},{"label":"Saving Throws","text":"Con +4"},{"label":"Damage Immunities","text":"fire, poison"},{"label":"Condition Immunities","text":"poisoned"},{"label":"Senses","text":"passive Perception 11"},{"label":"Languages","text":"Ignan"}],"traits":[{"name":"Heated Body","desc":"A creature that touches the azer or hits it with a melee attack while within 5 ft. of it takes 5 (1d10) fire damage."},{"name":"Heated Weapons","desc":"When the azer hits with a metal melee weapon, it deals an extra 3 (1d6) fire damage (included in the attack)."},{"name":"Illumination","desc":"The azer sheds bright light in a 10-foot radius and dim light for an additional 10 ft.."}],"actions":[],"reactions":[],"legendary":[]},"es":{"lines":[{"label":"Velocidad","text":"30 ft"},{"label":"Tiradas de salvación","text":"CON +4"},{"label":"Inmunidades al daño","text":"fuego, veneno"},{"label":"Inmunidades a estados","text":"envenenado"},{"label":"Sentidos","text":"Percepción pasiva 11"},{"label":"Idiomas","text":"Ígneo"}],"traits":[{"name":"Cuerpo candente","desc":"Una criatura que toque al azer o lo golpee con un ataque cuerpo a cuerpo estando a 5 ft o menos de él recibe 5 (1d10) de daño de fuego."},{"name":"Armas candentes","desc":"Cuando el azer impacta con un arma cuerpo a cuerpo de metal, inflige 3 (1d6) de daño de fuego adicional (incluido en el ataque)."},{"name":"Iluminación","desc":"El azer emite luz brillante en un radio de 10 ft y luz tenue 10 ft más allá."}],"actions":[],"reactions":[],"legendary":[]}},"srd:baboon":{"pt-BR":{"lines":[{"label":"Deslocamento","text":"30 ft, escalada 30 ft"},{"label":"Sentidos","text":"Percepção passiva 11"}],"traits":[{"name":"Táticas de Matilha","desc":"O babuíno tem vantagem nas jogadas de ataque contra uma criatura se ao menos um aliado do babuíno estiver a até 5 ft dela e não estiver incapacitado."}],"actions":[],"reactions":[],"legendary":[]},"en":{"lines":[{"label":"Speed","text":"30 ft, climb 30 ft"},{"label":"Senses","text":"passive Perception 11"}],"traits":[{"name":"Pack Tactics","desc":"The baboon has advantage on an attack roll against a creature if at least one of the baboon's allies is within 5 ft. of the creature and the ally isn't incapacitated."}],"actions":[],"reactions":[],"legendary":[]},"es":{"lines":[{"label":"Velocidad","text":"30 ft, trepar 30 ft"},{"label":"Sentidos","text":"Percepción pasiva 11"}],"traits":[{"name":"Tácticas de manada","desc":"El babuino tiene ventaja en las tiradas de ataque contra una criatura si al menos un aliado del babuino está a 5 ft o menos de ella y no está incapacitado."}],"actions":[],"reactions":[],"legendary":[]}},"srd:badger":{"pt-BR":{"lines":[{"label":"Deslocamento","text":"20 ft, escavação 5 ft"},{"label":"Sentidos","text":"visão no escuro 30 ft, Percepção passiva 11"}],"traits":[{"name":"Olfato Aguçado","desc":"O texugo tem vantagem em testes de Sabedoria (Percepção) que dependam do olfato."}],"actions":[],"reactions":[],"legendary":[]},"en":{"lines":[{"label":"Speed","text":"20 ft, burrow 5 ft"},{"label":"Senses","text":"darkvision 30 ft, passive Perception 11"}],"traits":[{"name":"Keen Smell","desc":"The badger has advantage on Wisdom (Perception) checks that rely on smell."}],"actions":[],"reactions":[],"legendary":[]},"es":{"lines":[{"label":"Velocidad","text":"20 ft, excavar 5 ft"},{"label":"Sentidos","text":"visión en la oscuridad 30 ft, Percepción pasiva 11"}],"traits":[{"name":"Olfato agudo","desc":"El tejón tiene ventaja en las pruebas de Sabiduría (Percepción) que dependan del olfato."}],"actions":[],"reactions":[],"legendary":[]}},"srd:balor":{"pt-BR":{"lines":[{"label":"Deslocamento","text":"40 ft, voo 80 ft"},{"label":"Testes de resistência","text":"FOR +14, CON +12, SAB +9, CAR +12"},{"label":"Resistência a dano","text":"frio, elétrico; concussão, perfurante e cortante de ataques não mágicos"},{"label":"Imunidade a dano","text":"fogo, veneno"},{"label":"Imunidade a condição","text":"envenenado"},{"label":"Sentidos","text":"visão verdadeira 120 ft, Percepção passiva 13"},{"label":"Idiomas","text":"Abissal, telepatia 120 ft"}],"traits":[{"name":"Agonia Mortal","desc":"Quando o balor morre, ele explode, e cada criatura a até 30 ft dele deve fazer um teste de resistência de Destreza CD 20; sofre 70 (20d6) de dano de fogo se falhar, ou metade se passar. A explosão incendeia objetos inflamáveis na área que ninguém esteja vestindo ou carregando, e destrói as armas do balor."},{"name":"Aura de Fogo","desc":"No início de cada turno do balor, cada criatura a até 5 ft dele sofre 10 (3d6) de dano de fogo, e objetos inflamáveis na aura que ninguém esteja vestindo ou carregando pegam fogo. Uma criatura que toque o balor ou o acerte com um ataque corpo a corpo estando a até 5 ft dele sofre 10 (3d6) de dano de fogo."},{"name":"Resistência à Magia","desc":"O balor tem vantagem em testes de resistência contra magias e outros efeitos mágicos."},{"name":"Armas Mágicas","desc":"Os ataques com arma do balor são mágicos."}],"actions":[{"name":"Ataques Múltiplos","desc":"O balor faz dois ataques: um com a espada longa e um com o chicote."},{"name":"Teletransporte","desc":"O balor se teletransporta magicamente, junto com o equipamento que veste ou carrega, até 120 ft para um espaço desocupado que possa ver."}],"reactions":[],"legendary":[]},"en":{"lines":[{"label":"Speed","text":"40 ft, fly 80 ft"},{"label":"Saving Throws","text":"Str +14, Con +12, Wis +9, Cha +12"},{"label":"Damage Resistances","text":"cold, lightning; bludgeoning, piercing, and slashing from nonmagical attacks"},{"label":"Damage Immunities","text":"fire, poison"},{"label":"Condition Immunities","text":"poisoned"},{"label":"Senses","text":"truesight 120 ft, passive Perception 13"},{"label":"Languages","text":"Abyssal, telepathy 120 ft."}],"traits":[{"name":"Death Throes","desc":"When the balor dies, it explodes, and each creature within 30 feet of it must make a DC 20 Dexterity saving throw, taking 70 (20d6) fire damage on a failed save, or half as much damage on a successful one. The explosion ignites flammable objects in that area that aren't being worn or carried, and it destroys the balor's weapons."},{"name":"Fire Aura","desc":"At the start of each of the balor's turns, each creature within 5 feet of it takes 10 (3d6) fire damage, and flammable objects in the aura that aren't being worn or carried ignite. A creature that touches the balor or hits it with a melee attack while within 5 feet of it takes 10 (3d6) fire damage."},{"name":"Magic Resistance","desc":"The balor has advantage on saving throws against spells and other magical effects."},{"name":"Magic Weapons","desc":"The balor's weapon attacks are magical."}],"actions":[{"name":"Multiattack","desc":"The balor makes two attacks: one with its longsword and one with its whip."},{"name":"Teleport","desc":"The balor magically teleports, along with any equipment it is wearing or carrying, up to 120 feet to an unoccupied space it can see."}],"reactions":[],"legendary":[]},"es":{"lines":[{"label":"Velocidad","text":"40 ft, volar 80 ft"},{"label":"Tiradas de salvación","text":"FUE +14, CON +12, SAB +9, CAR +12"},{"label":"Resistencias al daño","text":"frío, relámpago; contundente, perforante y cortante de ataques no mágicos"},{"label":"Inmunidades al daño","text":"fuego, veneno"},{"label":"Inmunidades a estados","text":"envenenado"},{"label":"Sentidos","text":"visión verdadera 120 ft, Percepción pasiva 13"},{"label":"Idiomas","text":"Abisal, telepatía 120 ft"}],"traits":[{"name":"Estertores de muerte","desc":"Cuando el balor muere, explota, y cada criatura a 30 ft o menos de él debe hacer una tirada de salvación de Destreza CD 20; recibe 70 (20d6) de daño de fuego si falla, o la mitad si la supera. La explosión prende fuego a los objetos inflamables del área que nadie lleve puestos o encima, y destruye las armas del balor."},{"name":"Aura de fuego","desc":"Al principio de cada turno del balor, cada criatura a 5 ft o menos de él recibe 10 (3d6) de daño de fuego, y los objetos inflamables del aura que nadie lleve puestos o encima prenden. Una criatura que toque al balor o lo golpee con un ataque cuerpo a cuerpo estando a 5 ft o menos de él recibe 10 (3d6) de daño de fuego."},{"name":"Resistencia mágica","desc":"El balor tiene ventaja en las tiradas de salvación contra conjuros y otros efectos mágicos."},{"name":"Armas mágicas","desc":"Los ataques con arma del balor son mágicos."}],"actions":[{"name":"Ataque múltiple","desc":"El balor hace dos ataques: uno con la espada larga y otro con el látigo."},{"name":"Teletransporte","desc":"El balor se teletransporta mágicamente, junto con el equipo que lleve puesto o encima, hasta 120 ft a un espacio desocupado que pueda ver."}],"reactions":[],"legendary":[]}},"srd:bandit":{"pt-BR":{"lines":[{"label":"Deslocamento","text":"30 ft"},{"label":"Sentidos","text":"Percepção passiva 10"},{"label":"Idiomas","text":"um idioma qualquer (geralmente Comum)"}],"traits":[],"actions":[],"reactions":[],"legendary":[]},"en":{"lines":[{"label":"Speed","text":"30 ft"},{"label":"Senses","text":"passive Perception 10"},{"label":"Languages","text":"any one language (usually Common)"}],"traits":[],"actions":[],"reactions":[],"legendary":[]},"es":{"lines":[{"label":"Velocidad","text":"30 ft"},{"label":"Sentidos","text":"Percepción pasiva 10"},{"label":"Idiomas","text":"un idioma cualquiera (normalmente común)"}],"traits":[],"actions":[],"reactions":[],"legendary":[]}},"srd:bandit-captain":{"pt-BR":{"lines":[{"label":"Deslocamento","text":"30 ft"},{"label":"Testes de resistência","text":"FOR +4, DES +5, SAB +2"},{"label":"Perícias","text":"Atletismo +4, Enganação +4"},{"label":"Sentidos","text":"Percepção passiva 10"},{"label":"Idiomas","text":"dois idiomas quaisquer"}],"traits":[],"actions":[{"name":"Ataques Múltiplos","desc":"O capitão faz três ataques corpo a corpo: dois com a cimitarra e um com a adaga. Ou faz dois ataques à distância com as adagas."}],"reactions":[{"name":"Aparar","desc":"O capitão soma 2 à CA contra um ataque corpo a corpo que o acertaria. Para isso, precisa ver o atacante e estar empunhando uma arma corpo a corpo."}],"legendary":[]},"en":{"lines":[{"label":"Speed","text":"30 ft"},{"label":"Saving Throws","text":"Str +4, Dex +5, Wis +2"},{"label":"Skills","text":"Athletics +4, Deception +4"},{"label":"Senses","text":"passive Perception 10"},{"label":"Languages","text":"any two languages"}],"traits":[],"actions":[{"name":"Multiattack","desc":"The captain makes three melee attacks: two with its scimitar and one with its dagger. Or the captain makes two ranged attacks with its daggers."}],"reactions":[{"name":"Parry","desc":"The captain adds 2 to its AC against one melee attack that would hit it. To do so, the captain must see the attacker and be wielding a melee weapon."}],"legendary":[]},"es":{"lines":[{"label":"Velocidad","text":"30 ft"},{"label":"Tiradas de salvación","text":"FUE +4, DES +5, SAB +2"},{"label":"Habilidades","text":"Atletismo +4, Engaño +4"},{"label":"Sentidos","text":"Percepción pasiva 10"},{"label":"Idiomas","text":"dos idiomas cualesquiera"}],"traits":[],"actions":[{"name":"Ataque múltiple","desc":"El capitán hace tres ataques cuerpo a cuerpo: dos con la cimitarra y uno con la daga. O hace dos ataques a distancia con las dagas."}],"reactions":[{"name":"Parada","desc":"El capitán suma 2 a su CA contra un ataque cuerpo a cuerpo que lo impactaría. Para ello, debe ver al atacante y empuñar un arma cuerpo a cuerpo."}],"legendary":[]}},"srd:barbed-devil":{"pt-BR":{"lines":[{"label":"Deslocamento","text":"30 ft"},{"label":"Testes de resistência","text":"FOR +6, CON +7, SAB +5, CAR +5"},{"label":"Perícias","text":"Enganação +5, Intuição +5, Percepção +8"},{"label":"Resistência a dano","text":"frio; concussão, perfurante e cortante de ataques não mágicos feitos sem armas de prata"},{"label":"Imunidade a dano","text":"fogo, veneno"},{"label":"Imunidade a condição","text":"envenenado"},{"label":"Sentidos","text":"visão no escuro 120 ft, Percepção passiva 18"},{"label":"Idiomas","text":"Infernal, telepatia 120 ft"}],"traits":[{"name":"Couro Farpado","desc":"No início de cada um dos seus turnos, o diabo farpado causa 5 (1d10) de dano perfurante a qualquer criatura que o esteja agarrando."},{"name":"Visão do Diabo","desc":"A escuridão mágica não atrapalha a visão no escuro do diabo."},{"name":"Resistência à Magia","desc":"O diabo tem vantagem em testes de resistência contra magias e outros efeitos mágicos."}],"actions":[{"name":"Ataques Múltiplos","desc":"O diabo faz três ataques corpo a corpo: um com a cauda e dois com as garras. Ou pode usar Arremessar Chama duas vezes."}],"reactions":[],"legendary":[]},"en":{"lines":[{"label":"Speed","text":"30 ft"},{"label":"Saving Throws","text":"Str +6, Con +7, Wis +5, Cha +5"},{"label":"Skills","text":"Deception +5, Insight +5, Perception +8"},{"label":"Damage Resistances","text":"cold; bludgeoning, piercing, and slashing from nonmagical attacks not made with silvered weapons"},{"label":"Damage Immunities","text":"fire, poison"},{"label":"Condition Immunities","text":"poisoned"},{"label":"Senses","text":"darkvision 120 ft, passive Perception 18"},{"label":"Languages","text":"Infernal, telepathy 120 ft."}],"traits":[{"name":"Barbed Hide","desc":"At the start of each of its turns, the barbed devil deals 5 (1d10) piercing damage to any creature grappling it."},{"name":"Devil's Sight","desc":"Magical darkness doesn't impede the devil's darkvision."},{"name":"Magic Resistance","desc":"The devil has advantage on saving throws against spells and other magical effects."}],"actions":[{"name":"Multiattack","desc":"The devil makes three melee attacks: one with its tail and two with its claws. Alternatively, it can use Hurl Flame twice."}],"reactions":[],"legendary":[]},"es":{"lines":[{"label":"Velocidad","text":"30 ft"},{"label":"Tiradas de salvación","text":"FUE +6, CON +7, SAB +5, CAR +5"},{"label":"Habilidades","text":"Engaño +5, Perspicacia +5, Percepción +8"},{"label":"Resistencias al daño","text":"frío; contundente, perforante y cortante de ataques no mágicos hechos sin armas de plata"},{"label":"Inmunidades al daño","text":"fuego, veneno"},{"label":"Inmunidades a estados","text":"envenenado"},{"label":"Sentidos","text":"visión en la oscuridad 120 ft, Percepción pasiva 18"},{"label":"Idiomas","text":"Infernal, telepatía 120 ft"}],"traits":[{"name":"Piel espinosa","desc":"Al principio de cada uno de sus turnos, el diablo espinoso inflige 5 (1d10) de daño perforante a cualquier criatura que lo esté agarrando."},{"name":"Vista del diablo","desc":"La oscuridad mágica no impide la visión en la oscuridad del diablo."},{"name":"Resistencia mágica","desc":"El diablo tiene ventaja en las tiradas de salvación contra conjuros y otros efectos mágicos."}],"actions":[{"name":"Ataque múltiple","desc":"El diablo hace tres ataques cuerpo a cuerpo: uno con la cola y dos con las garras. O puede usar Arrojar llama dos veces."}],"reactions":[],"legendary":[]}},"srd:basilisk":{"pt-BR":{"lines":[{"label":"Deslocamento","text":"20 ft"},{"label":"Sentidos","text":"visão no escuro 60 ft, Percepção passiva 9"}],"traits":[{"name":"Olhar Petrificante","desc":"Se uma criatura começar o turno a até 30 ft do basilisco e os dois puderem se ver, o basilisco pode obrigá-la a fazer um teste de resistência de Constituição CD 12, se não estiver incapacitado. Se falhar, a criatura começa a virar pedra magicamente e fica impedida. Ela deve repetir o teste no fim do seu próximo turno: se passar, o efeito acaba; se falhar, fica petrificada até ser libertada pela magia restauração maior ou outra magia.\nUma criatura que não esteja surpresa pode desviar o olhar para evitar o teste no início do turno. Se fizer isso, não pode ver o basilisco até o início do seu próximo turno, quando pode desviar o olhar de novo. Se olhar para o basilisco nesse meio-tempo, deve fazer o teste na hora.\nSe o basilisco vir o próprio reflexo a até 30 ft sob luz plena, ele se confunde com um rival e usa o olhar em si mesmo."}],"actions":[],"reactions":[],"legendary":[]},"en":{"lines":[{"label":"Speed","text":"20 ft"},{"label":"Senses","text":"darkvision 60 ft, passive Perception 9"}],"traits":[{"name":"Petrifying Gaze","desc":"If a creature starts its turn within 30 ft. of the basilisk and the two of them can see each other, the basilisk can force the creature to make a DC 12 Constitution saving throw if the basilisk isn't incapacitated. On a failed save, the creature magically begins to turn to stone and is restrained. It must repeat the saving throw at the end of its next turn. On a success, the effect ends. On a failure, the creature is petrified until freed by the greater restoration spell or other magic.\nA creature that isn't surprised can avert its eyes to avoid the saving throw at the start of its turn. If it does so, it can't see the basilisk until the start of its next turn, when it can avert its eyes again. If it looks at the basilisk in the meantime, it must immediately make the save.\nIf the basilisk sees its reflection within 30 ft. of it in bright light, it mistakes itself for a rival and targets itself with its gaze."}],"actions":[],"reactions":[],"legendary":[]},"es":{"lines":[{"label":"Velocidad","text":"20 ft"},{"label":"Sentidos","text":"visión en la oscuridad 60 ft, Percepción pasiva 9"}],"traits":[{"name":"Mirada petrificante","desc":"Si una criatura empieza su turno a 30 ft o menos del basilisco y ambos pueden verse, el basilisco puede obligarla a hacer una tirada de salvación de Constitución CD 12, si no está incapacitado. Si falla, la criatura empieza a convertirse en piedra mágicamente y queda apresada. Debe repetir la tirada al final de su siguiente turno: si la supera, el efecto termina; si falla, queda petrificada hasta que la libere el conjuro restablecimiento mayor u otra magia.\nUna criatura que no esté sorprendida puede apartar la mirada para evitar la tirada al principio de su turno. Si lo hace, no puede ver al basilisco hasta el principio de su siguiente turno, cuando puede volver a apartarla. Si mira al basilisco mientras tanto, debe hacer la tirada de inmediato.\nSi el basilisco ve su reflejo a 30 ft o menos bajo luz brillante, se confunde con un rival y usa la mirada contra sí mismo."}],"actions":[],"reactions":[],"legendary":[]}},"srd:bat":{"pt-BR":{"lines":[{"label":"Deslocamento","text":"5 ft, voo 30 ft"},{"label":"Sentidos","text":"percepção às cegas 60 ft, Percepção passiva 11"}],"traits":[{"name":"Ecolocalização","desc":"O morcego não pode usar a percepção às cegas enquanto estiver surdo."},{"name":"Audição Aguçada","desc":"O morcego tem vantagem em testes de Sabedoria (Percepção) que dependam da audição."}],"actions":[],"reactions":[],"legendary":[]},"en":{"lines":[{"label":"Speed","text":"5 ft, fly 30 ft"},{"label":"Senses","text":"blindsight 60 ft, passive Perception 11"}],"traits":[{"name":"Echolocation","desc":"The bat can't use its blindsight while deafened."},{"name":"Keen Hearing","desc":"The bat has advantage on Wisdom (Perception) checks that rely on hearing."}],"actions":[],"reactions":[],"legendary":[]},"es":{"lines":[{"label":"Velocidad","text":"5 ft, volar 30 ft"},{"label":"Sentidos","text":"vista ciega 60 ft, Percepción pasiva 11"}],"traits":[{"name":"Ecolocalización","desc":"El murciélago no puede usar su vista ciega mientras esté ensordecido."},{"name":"Oído agudo","desc":"El murciélago tiene ventaja en las pruebas de Sabiduría (Percepción) que dependan del oído."}],"actions":[],"reactions":[],"legendary":[]}},"srd:bearded-devil":{"pt-BR":{"lines":[{"label":"Deslocamento","text":"30 ft"},{"label":"Testes de resistência","text":"FOR +5, CON +4, SAB +2"},{"label":"Resistência a dano","text":"frio; concussão, perfurante e cortante de ataques não mágicos feitos sem armas de prata"},{"label":"Imunidade a dano","text":"fogo, veneno"},{"label":"Imunidade a condição","text":"envenenado"},{"label":"Sentidos","text":"visão no escuro 120 ft, Percepção passiva 10"},{"label":"Idiomas","text":"Infernal, telepatia 120 ft"}],"traits":[{"name":"Visão do Diabo","desc":"A escuridão mágica não atrapalha a visão no escuro do diabo."},{"name":"Resistência à Magia","desc":"O diabo tem vantagem em testes de resistência contra magias e outros efeitos mágicos."},{"name":"Inabalável","desc":"O diabo não pode ficar amedrontado enquanto puder ver uma criatura aliada a até 30 ft."}],"actions":[{"name":"Ataques Múltiplos","desc":"O diabo faz dois ataques: um com a barba e um com a glaive."}],"reactions":[],"legendary":[]},"en":{"lines":[{"label":"Speed","text":"30 ft"},{"label":"Saving Throws","text":"Str +5, Con +4, Wis +2"},{"label":"Damage Resistances","text":"cold; bludgeoning, piercing, and slashing from nonmagical attacks not made with silvered weapons"},{"label":"Damage Immunities","text":"fire, poison"},{"label":"Condition Immunities","text":"poisoned"},{"label":"Senses","text":"darkvision 120 ft, passive Perception 10"},{"label":"Languages","text":"Infernal, telepathy 120 ft."}],"traits":[{"name":"Devil's Sight","desc":"Magical darkness doesn't impede the devil's darkvision."},{"name":"Magic Resistance","desc":"The devil has advantage on saving throws against spells and other magical effects."},{"name":"Steadfast","desc":"The devil can't be frightened while it can see an allied creature within 30 feet of it."}],"actions":[{"name":"Multiattack","desc":"The devil makes two attacks: one with its beard and one with its glaive."}],"reactions":[],"legendary":[]},"es":{"lines":[{"label":"Velocidad","text":"30 ft"},{"label":"Tiradas de salvación","text":"FUE +5, CON +4, SAB +2"},{"label":"Resistencias al daño","text":"frío; contundente, perforante y cortante de ataques no mágicos hechos sin armas de plata"},{"label":"Inmunidades al daño","text":"fuego, veneno"},{"label":"Inmunidades a estados","text":"envenenado"},{"label":"Sentidos","text":"visión en la oscuridad 120 ft, Percepción pasiva 10"},{"label":"Idiomas","text":"Infernal, telepatía 120 ft"}],"traits":[{"name":"Vista del diablo","desc":"La oscuridad mágica no impide la visión en la oscuridad del diablo."},{"name":"Resistencia mágica","desc":"El diablo tiene ventaja en las tiradas de salvación contra conjuros y otros efectos mágicos."},{"name":"Firme","desc":"El diablo no puede quedar asustado mientras pueda ver a una criatura aliada a 30 ft o menos."}],"actions":[{"name":"Ataque múltiple","desc":"El diablo hace dos ataques: uno con la barba y otro con la guja."}],"reactions":[],"legendary":[]}},"srd:behir":{"pt-BR":{"lines":[{"label":"Deslocamento","text":"50 ft, escalada 40 ft"},{"label":"Perícias","text":"Percepção +6, Furtividade +7"},{"label":"Imunidade a dano","text":"elétrico"},{"label":"Sentidos","text":"visão no escuro 90 ft, Percepção passiva 16"},{"label":"Idiomas","text":"Dracônico"}],"traits":[],"actions":[{"name":"Ataques Múltiplos","desc":"O behir faz dois ataques: um de mordida e um de constrição."},{"name":"Sopro Elétrico (recarga 5–6)","desc":"O behir exala uma linha de relâmpago de 20 ft de comprimento por 5 ft de largura. Cada criatura na linha deve fazer um teste de resistência de Destreza CD 16; sofre 66 (12d10) de dano elétrico se falhar, ou metade se passar."},{"name":"Engolir","desc":"O behir faz um ataque de mordida contra um alvo Médio ou menor que esteja agarrando. Se acertar, o alvo também é engolido e deixa de estar agarrado. Engolido, o alvo fica cego e impedido, tem cobertura total contra ataques e efeitos de fora do behir, e sofre 21 (6d6) de dano de ácido no início de cada turno do behir. O behir só pode ter uma criatura engolida por vez.\nSe o behir sofrer 30 de dano ou mais num único turno vindo da criatura engolida, deve passar num teste de resistência de Constituição CD 14 no fim desse turno ou regurgita a criatura, que cai num espaço a até 10 ft do behir. Se o behir morrer, a criatura engolida deixa de estar impedida e pode sair do corpo usando 15 ft de deslocamento, saindo caída."}],"reactions":[],"legendary":[]},"en":{"lines":[{"label":"Speed","text":"50 ft, climb 40 ft"},{"label":"Skills","text":"Perception +6, Stealth +7"},{"label":"Damage Immunities","text":"lightning"},{"label":"Senses","text":"darkvision 90 ft, passive Perception 16"},{"label":"Languages","text":"Draconic"}],"traits":[],"actions":[{"name":"Multiattack","desc":"The behir makes two attacks: one with its bite and one to constrict."},{"name":"Lightning Breath (Recharge 5–6)","desc":"The behir exhales a line of lightning that is 20 ft. long and 5 ft. wide. Each creature in that line must make a DC 16 Dexterity saving throw, taking 66 (12d10) lightning damage on a failed save, or half as much damage on a successful one."},{"name":"Swallow","desc":"The behir makes one bite attack against a Medium or smaller target it is grappling. If the attack hits, the target is also swallowed, and the grapple ends. While swallowed, the target is blinded and restrained, it has total cover against attacks and other effects outside the behir, and it takes 21 (6d6) acid damage at the start of each of the behir's turns. A behir can have only one creature swallowed at a time.\nIf the behir takes 30 damage or more on a single turn from the swallowed creature, the behir must succeed on a DC 14 Constitution saving throw at the end of that turn or regurgitate the creature, which falls prone in a space within 10 ft. of the behir. If the behir dies, a swallowed creature is no longer restrained by it and can escape from the corpse by using 15 ft. of movement, exiting prone."}],"reactions":[],"legendary":[]},"es":{"lines":[{"label":"Velocidad","text":"50 ft, trepar 40 ft"},{"label":"Habilidades","text":"Percepción +6, Sigilo +7"},{"label":"Inmunidades al daño","text":"relámpago"},{"label":"Sentidos","text":"visión en la oscuridad 90 ft, Percepción pasiva 16"},{"label":"Idiomas","text":"Dracónico"}],"traits":[],"actions":[{"name":"Ataque múltiple","desc":"El behir hace dos ataques: uno de mordisco y otro de constreñir."},{"name":"Aliento de relámpago (recarga 5–6)","desc":"El behir exhala una línea de relámpago de 20 ft de largo y 5 ft de ancho. Cada criatura en la línea debe hacer una tirada de salvación de Destreza CD 16; recibe 66 (12d10) de daño de relámpago si falla, o la mitad si la supera."},{"name":"Engullir","desc":"El behir hace un ataque de mordisco contra un objetivo Mediano o más pequeño al que esté agarrando. Si impacta, el objetivo también es engullido y deja de estar agarrado. Mientras está engullido, el objetivo está cegado y apresado, tiene cobertura total contra ataques y efectos de fuera del behir, y recibe 21 (6d6) de daño de ácido al principio de cada turno del behir. El behir solo puede tener una criatura engullida a la vez.\nSi el behir recibe 30 de daño o más en un solo turno de la criatura engullida, debe superar una tirada de salvación de Constitución CD 14 al final de ese turno o regurgita a la criatura, que cae derribada en un espacio a 10 ft o menos del behir. Si el behir muere, la criatura engullida deja de estar apresada y puede salir del cadáver usando 15 ft de movimiento, quedando derribada."}],"reactions":[],"legendary":[]}},"srd:berserker":{"pt-BR":{"lines":[{"label":"Deslocamento","text":"30 ft"},{"label":"Sentidos","text":"Percepção passiva 10"},{"label":"Idiomas","text":"um idioma qualquer (geralmente Comum)"}],"traits":[{"name":"Imprudente","desc":"No início do seu turno, o berserker pode ganhar vantagem em todas as jogadas de ataque corpo a corpo com arma nesse turno, mas as jogadas de ataque contra ele têm vantagem até o início do seu próximo turno."}],"actions":[],"reactions":[],"legendary":[]},"en":{"lines":[{"label":"Speed","text":"30 ft"},{"label":"Senses","text":"passive Perception 10"},{"label":"Languages","text":"any one language (usually Common)"}],"traits":[{"name":"Reckless","desc":"At the start of its turn, the berserker can gain advantage on all melee weapon attack rolls during that turn, but attack rolls against it have advantage until the start of its next turn."}],"actions":[],"reactions":[],"legendary":[]},"es":{"lines":[{"label":"Velocidad","text":"30 ft"},{"label":"Sentidos","text":"Percepción pasiva 10"},{"label":"Idiomas","text":"un idioma cualquiera (normalmente común)"}],"traits":[{"name":"Temerario","desc":"Al principio de su turno, el berserker puede obtener ventaja en todas las tiradas de ataque con arma cuerpo a cuerpo durante ese turno, pero las tiradas de ataque contra él tienen ventaja hasta el principio de su siguiente turno."}],"actions":[],"reactions":[],"legendary":[]}},"srd:black-bear":{"pt-BR":{"lines":[{"label":"Deslocamento","text":"40 ft, escalada 30 ft"},{"label":"Sentidos","text":"Percepção passiva 13"}],"traits":[{"name":"Olfato Aguçado","desc":"O urso tem vantagem em testes de Sabedoria (Percepção) que dependam do olfato."}],"actions":[{"name":"Ataques Múltiplos","desc":"O urso faz dois ataques: um de mordida e um de garras."}],"reactions":[],"legendary":[]},"en":{"lines":[{"label":"Speed","text":"40 ft, climb 30 ft"},{"label":"Senses","text":"passive Perception 13"}],"traits":[{"name":"Keen Smell","desc":"The bear has advantage on Wisdom (Perception) checks that rely on smell."}],"actions":[{"name":"Multiattack","desc":"The bear makes two attacks: one with its bite and one with its claws."}],"reactions":[],"legendary":[]},"es":{"lines":[{"label":"Velocidad","text":"40 ft, trepar 30 ft"},{"label":"Sentidos","text":"Percepción pasiva 13"}],"traits":[{"name":"Olfato agudo","desc":"El oso tiene ventaja en las pruebas de Sabiduría (Percepción) que dependan del olfato."}],"actions":[{"name":"Ataque múltiple","desc":"El oso hace dos ataques: uno de mordisco y otro de garras."}],"reactions":[],"legendary":[]}},"srd:black-pudding":{"pt-BR":{"lines":[{"label":"Deslocamento","text":"20 ft, escalada 20 ft"},{"label":"Imunidade a dano","text":"ácido, frio, elétrico, cortante"},{"label":"Imunidade a condição","text":"cego, enfeitiçado, surdo, exaustão, amedrontado, caído"},{"label":"Sentidos","text":"percepção às cegas 60 ft, Percepção passiva 8"}],"traits":[{"name":"Amorfo","desc":"O pudim pode passar por um espaço de apenas 2,5 cm de largura sem se espremer."},{"name":"Forma Corrosiva","desc":"Uma criatura que toque o pudim ou o acerte com um ataque corpo a corpo estando a até 5 ft dele sofre 4 (1d8) de dano de ácido. Qualquer arma não mágica de metal ou madeira que acerte o pudim é corroída: depois de causar o dano, recebe uma penalidade permanente e cumulativa de -1 nas jogadas de dano; se a penalidade chegar a -5, a arma é destruída. Munição não mágica de metal ou madeira que acerte o pudim é destruída depois de causar o dano. O pudim corrói 5 cm de madeira ou metal não mágicos em 1 rodada."},{"name":"Escalar como Aranha","desc":"O pudim pode escalar superfícies difíceis, inclusive de cabeça para baixo no teto, sem precisar fazer teste de habilidade."}],"actions":[],"reactions":[{"name":"Dividir","desc":"Quando um pudim Médio ou maior sofre dano elétrico ou cortante, ele se divide em dois pudins novos, se tiver pelo menos 10 pontos de vida. Cada pudim novo tem metade dos pontos de vida do original, arredondado para baixo, e é um tamanho menor que ele."}],"legendary":[]},"en":{"lines":[{"label":"Speed","text":"20 ft, climb 20 ft"},{"label":"Damage Immunities","text":"acid, cold, lightning, slashing"},{"label":"Condition Immunities","text":"blinded, charmed, deafened, exhaustion, frightened, prone"},{"label":"Senses","text":"blindsight 60 ft, passive Perception 8"}],"traits":[{"name":"Amorphous","desc":"The pudding can move through a space as narrow as 1 inch wide without squeezing."},{"name":"Corrosive Form","desc":"A creature that touches the pudding or hits it with a melee attack while within 5 feet of it takes 4 (1d8) acid damage. Any nonmagical weapon made of metal or wood that hits the pudding corrodes. After dealing damage, the weapon takes a permanent and cumulative -1 penalty to damage rolls. If its penalty drops to -5, the weapon is destroyed. Nonmagical ammunition made of metal or wood that hits the pudding is destroyed after dealing damage. The pudding can eat through 2-inch-thick, nonmagical wood or metal in 1 round."},{"name":"Spider Climb","desc":"The pudding can climb difficult surfaces, including upside down on ceilings, without needing to make an ability check."}],"actions":[],"reactions":[{"name":"Split","desc":"When a pudding that is Medium or larger is subjected to lightning or slashing damage, it splits into two new puddings if it has at least 10 hit points. Each new pudding has hit points equal to half the original pudding's, rounded down. New puddings are one size smaller than the original pudding."}],"legendary":[]},"es":{"lines":[{"label":"Velocidad","text":"20 ft, trepar 20 ft"},{"label":"Inmunidades al daño","text":"ácido, frío, relámpago, cortante"},{"label":"Inmunidades a estados","text":"cegado, hechizado, ensordecido, agotamiento, asustado, derribado"},{"label":"Sentidos","text":"vista ciega 60 ft, Percepción pasiva 8"}],"traits":[{"name":"Amorfo","desc":"El pudin puede pasar por un espacio de solo 2,5 cm de ancho sin apretarse."},{"name":"Forma corrosiva","desc":"Una criatura que toque al pudin o lo golpee con un ataque cuerpo a cuerpo estando a 5 ft o menos de él recibe 4 (1d8) de daño de ácido. Cualquier arma no mágica de metal o madera que impacte al pudin se corroe: tras infligir el daño, sufre un penalizador permanente y acumulativo de -1 a las tiradas de daño; si llega a -5, el arma se destruye. La munición no mágica de metal o madera que impacte al pudin se destruye tras infligir el daño. El pudin atraviesa 5 cm de madera o metal no mágicos en 1 asalto."},{"name":"Trepar cual arácnido","desc":"El pudin puede trepar por superficies difíciles, incluso boca abajo por el techo, sin necesidad de hacer una prueba de característica."}],"actions":[],"reactions":[{"name":"Dividirse","desc":"Cuando un pudin Mediano o más grande recibe daño de relámpago o cortante, se divide en dos pudines nuevos si tiene al menos 10 puntos de golpe. Cada pudin nuevo tiene la mitad de los puntos de golpe del original, redondeando hacia abajo, y es una categoría de tamaño más pequeño."}],"legendary":[]}},"srd:blink-dog":{"pt-BR":{"lines":[{"label":"Deslocamento","text":"40 ft"},{"label":"Perícias","text":"Percepção +3, Furtividade +5"},{"label":"Sentidos","text":"Percepção passiva 10"},{"label":"Idiomas","text":"Cão Teleportador, entende Silvestre mas não fala"}],"traits":[{"name":"Audição e Olfato Aguçados","desc":"O cão tem vantagem em testes de Sabedoria (Percepção) que dependam da audição ou do olfato."}],"actions":[{"name":"Teletransporte","desc":"O cão se teletransporta magicamente, junto com o equipamento que veste ou carrega, até 40 ft para um espaço desocupado que possa ver. Antes ou depois de se teletransportar, pode fazer um ataque de mordida."}],"reactions":[],"legendary":[]},"en":{"lines":[{"label":"Speed","text":"40 ft"},{"label":"Skills","text":"Perception +3, Stealth +5"},{"label":"Senses","text":"passive Perception 10"},{"label":"Languages","text":"Blink Dog, understands Sylvan but can't speak it"}],"traits":[{"name":"Keen Hearing and Smell","desc":"The dog has advantage on Wisdom (Perception) checks that rely on hearing or smell."}],"actions":[{"name":"Teleport","desc":"The dog magically teleports, along with any equipment it is wearing or carrying, up to 40 ft. to an unoccupied space it can see. Before or after teleporting, the dog can make one bite attack."}],"reactions":[],"legendary":[]},"es":{"lines":[{"label":"Velocidad","text":"40 ft"},{"label":"Habilidades","text":"Percepción +3, Sigilo +5"},{"label":"Sentidos","text":"Percepción pasiva 10"},{"label":"Idiomas","text":"Perro intermitente, entiende silvano pero no lo habla"}],"traits":[{"name":"Oído y olfato agudos","desc":"El perro tiene ventaja en las pruebas de Sabiduría (Percepción) que dependan del oído o del olfato."}],"actions":[{"name":"Teletransporte","desc":"El perro se teletransporta mágicamente, junto con el equipo que lleve puesto o encima, hasta 40 ft a un espacio desocupado que pueda ver. Antes o después de teletransportarse, puede hacer un ataque de mordisco."}],"reactions":[],"legendary":[]}},"srd:blood-hawk":{"pt-BR":{"lines":[{"label":"Deslocamento","text":"10 ft, voo 60 ft"},{"label":"Perícias","text":"Percepção +4"},{"label":"Sentidos","text":"Percepção passiva 14"}],"traits":[{"name":"Visão Aguçada","desc":"O falcão tem vantagem em testes de Sabedoria (Percepção) que dependam da visão."},{"name":"Táticas de Matilha","desc":"O falcão tem vantagem nas jogadas de ataque contra uma criatura se ao menos um aliado do falcão estiver a até 5 ft dela e não estiver incapacitado."}],"actions":[],"reactions":[],"legendary":[]},"en":{"lines":[{"label":"Speed","text":"10 ft, fly 60 ft"},{"label":"Skills","text":"Perception +4"},{"label":"Senses","text":"passive Perception 14"}],"traits":[{"name":"Keen Sight","desc":"The hawk has advantage on Wisdom (Perception) checks that rely on sight."},{"name":"Pack Tactics","desc":"The hawk has advantage on an attack roll against a creature if at least one of the hawk's allies is within 5 ft. of the creature and the ally isn't incapacitated."}],"actions":[],"reactions":[],"legendary":[]},"es":{"lines":[{"label":"Velocidad","text":"10 ft, volar 60 ft"},{"label":"Habilidades","text":"Percepción +4"},{"label":"Sentidos","text":"Percepción pasiva 14"}],"traits":[{"name":"Vista aguda","desc":"El halcón tiene ventaja en las pruebas de Sabiduría (Percepción) que dependan de la vista."},{"name":"Tácticas de manada","desc":"El halcón tiene ventaja en las tiradas de ataque contra una criatura si al menos un aliado del halcón está a 5 ft o menos de ella y no está incapacitado."}],"actions":[],"reactions":[],"legendary":[]}},"srd:boar":{"pt-BR":{"lines":[{"label":"Deslocamento","text":"40 ft"},{"label":"Sentidos","text":"Percepção passiva 9"}],"traits":[{"name":"Investida","desc":"Se o javali se mover pelo menos 20 ft em linha reta até um alvo e o acertar com um ataque de presa no mesmo turno, o alvo sofre 3 (1d6) de dano cortante extra. Se o alvo for uma criatura, deve passar num teste de resistência de Força CD 11 ou cai."},{"name":"Implacável (recarrega após descanso curto ou longo)","desc":"Se o javali sofrer 7 de dano ou menos que o deixaria com 0 pontos de vida, ele fica com 1 ponto de vida em vez disso."}],"actions":[],"reactions":[],"legendary":[]},"en":{"lines":[{"label":"Speed","text":"40 ft"},{"label":"Senses","text":"passive Perception 9"}],"traits":[{"name":"Charge","desc":"If the boar moves at least 20 ft. straight toward a target and then hits it with a tusk attack on the same turn, the target takes an extra 3 (1d6) slashing damage. If the target is a creature, it must succeed on a DC 11 Strength saving throw or be knocked prone."},{"name":"Relentless (Recharges after a Short or Long Rest)","desc":"If the boar takes 7 damage or less that would reduce it to 0 hit points, it is reduced to 1 hit point instead."}],"actions":[],"reactions":[],"legendary":[]},"es":{"lines":[{"label":"Velocidad","text":"40 ft"},{"label":"Sentidos","text":"Percepción pasiva 9"}],"traits":[{"name":"Carga","desc":"Si el jabalí se mueve al menos 20 ft en línea recta hacia un objetivo y lo impacta con un ataque de colmillo en el mismo turno, el objetivo recibe 3 (1d6) de daño cortante adicional. Si el objetivo es una criatura, debe superar una tirada de salvación de Fuerza CD 11 o queda derribado."},{"name":"Implacable (se recarga tras un descanso corto o largo)","desc":"Si el jabalí recibe 7 de daño o menos que lo dejaría a 0 puntos de golpe, en su lugar queda con 1 punto de golpe."}],"actions":[],"reactions":[],"legendary":[]}},"srd:bone-devil":{"pt-BR":{"lines":[{"label":"Deslocamento","text":"40 ft, voo 40 ft"},{"label":"Testes de resistência","text":"INT +5, SAB +6, CAR +7"},{"label":"Perícias","text":"Enganação +7, Intuição +6"},{"label":"Resistência a dano","text":"frio; concussão, perfurante e cortante de ataques não mágicos feitos sem armas de prata"},{"label":"Imunidade a dano","text":"fogo, veneno"},{"label":"Imunidade a condição","text":"envenenado"},{"label":"Sentidos","text":"visão no escuro 120 ft, Percepção passiva 9"},{"label":"Idiomas","text":"Infernal, telepatia 120 ft"}],"traits":[{"name":"Visão do Diabo","desc":"A escuridão mágica não atrapalha a visão no escuro do diabo."},{"name":"Resistência à Magia","desc":"O diabo tem vantagem em testes de resistência contra magias e outros efeitos mágicos."}],"actions":[{"name":"Ataques Múltiplos","desc":"O diabo faz três ataques: dois com as garras e um com o ferrão."}],"reactions":[],"legendary":[]},"en":{"lines":[{"label":"Speed","text":"40 ft, fly 40 ft"},{"label":"Saving Throws","text":"Int +5, Wis +6, Cha +7"},{"label":"Skills","text":"Deception +7, Insight +6"},{"label":"Damage Resistances","text":"cold; bludgeoning, piercing, and slashing from nonmagical attacks not made with silvered weapons"},{"label":"Damage Immunities","text":"fire, poison"},{"label":"Condition Immunities","text":"poisoned"},{"label":"Senses","text":"darkvision 120 ft, passive Perception 9"},{"label":"Languages","text":"Infernal, telepathy 120 ft."}],"traits":[{"name":"Devil's Sight","desc":"Magical darkness doesn't impede the devil's darkvision."},{"name":"Magic Resistance","desc":"The devil has advantage on saving throws against spells and other magical effects."}],"actions":[{"name":"Multiattack","desc":"The devil makes three attacks: two with its claws and one with its sting."}],"reactions":[],"legendary":[]},"es":{"lines":[{"label":"Velocidad","text":"40 ft, volar 40 ft"},{"label":"Tiradas de salvación","text":"INT +5, SAB +6, CAR +7"},{"label":"Habilidades","text":"Engaño +7, Perspicacia +6"},{"label":"Resistencias al daño","text":"frío; contundente, perforante y cortante de ataques no mágicos hechos sin armas de plata"},{"label":"Inmunidades al daño","text":"fuego, veneno"},{"label":"Inmunidades a estados","text":"envenenado"},{"label":"Sentidos","text":"visión en la oscuridad 120 ft, Percepción pasiva 9"},{"label":"Idiomas","text":"Infernal, telepatía 120 ft"}],"traits":[{"name":"Vista del diablo","desc":"La oscuridad mágica no impide la visión en la oscuridad del diablo."},{"name":"Resistencia mágica","desc":"El diablo tiene ventaja en las tiradas de salvación contra conjuros y otros efectos mágicos."}],"actions":[{"name":"Ataque múltiple","desc":"El diablo hace tres ataques: dos con las garras y uno con el aguijón."}],"reactions":[],"legendary":[]}},"srd:brown-bear":{"pt-BR":{"lines":[{"label":"Deslocamento","text":"40 ft, escalada 30 ft"},{"label":"Perícias","text":"Percepção +3"},{"label":"Sentidos","text":"Percepção passiva 13"}],"traits":[{"name":"Olfato Aguçado","desc":"O urso tem vantagem em testes de Sabedoria (Percepção) que dependam do olfato."}],"actions":[{"name":"Ataques Múltiplos","desc":"O urso faz dois ataques: um de mordida e um de garras."}],"reactions":[],"legendary":[]},"en":{"lines":[{"label":"Speed","text":"40 ft, climb 30 ft"},{"label":"Skills","text":"Perception +3"},{"label":"Senses","text":"passive Perception 13"}],"traits":[{"name":"Keen Smell","desc":"The bear has advantage on Wisdom (Perception) checks that rely on smell."}],"actions":[{"name":"Multiattack","desc":"The bear makes two attacks: one with its bite and one with its claws."}],"reactions":[],"legendary":[]},"es":{"lines":[{"label":"Velocidad","text":"40 ft, trepar 30 ft"},{"label":"Habilidades","text":"Percepción +3"},{"label":"Sentidos","text":"Percepción pasiva 13"}],"traits":[{"name":"Olfato agudo","desc":"El oso tiene ventaja en las pruebas de Sabiduría (Percepción) que dependan del olfato."}],"actions":[{"name":"Ataque múltiple","desc":"El oso hace dos ataques: uno de mordisco y otro de garras."}],"reactions":[],"legendary":[]}},"srd:bugbear":{"pt-BR":{"lines":[{"label":"Deslocamento","text":"30 ft"},{"label":"Perícias","text":"Furtividade +6, Sobrevivência +2"},{"label":"Sentidos","text":"visão no escuro 60 ft, Percepção passiva 10"},{"label":"Idiomas","text":"Comum, Goblin"}],"traits":[{"name":"Bruto","desc":"Uma arma corpo a corpo causa um dado extra do seu dano quando o bugbear acerta com ela (já incluído no ataque)."},{"name":"Ataque Surpresa","desc":"Se o bugbear surpreender uma criatura e a acertar com um ataque na primeira rodada de combate, o alvo sofre 7 (2d6) de dano extra desse ataque."}],"actions":[],"reactions":[],"legendary":[]},"en":{"lines":[{"label":"Speed","text":"30 ft"},{"label":"Skills","text":"Stealth +6, Survival +2"},{"label":"Senses","text":"darkvision 60 ft, passive Perception 10"},{"label":"Languages","text":"Common, Goblin"}],"traits":[{"name":"Brute","desc":"A melee weapon deals one extra die of its damage when the bugbear hits with it (included in the attack)."},{"name":"Surprise Attack","desc":"If the bugbear surprises a creature and hits it with an attack during the first round of combat, the target takes an extra 7 (2d6) damage from the attack."}],"actions":[],"reactions":[],"legendary":[]},"es":{"lines":[{"label":"Velocidad","text":"30 ft"},{"label":"Habilidades","text":"Sigilo +6, Supervivencia +2"},{"label":"Sentidos","text":"visión en la oscuridad 60 ft, Percepción pasiva 10"},{"label":"Idiomas","text":"Común, goblin"}],"traits":[{"name":"Bruto","desc":"Un arma cuerpo a cuerpo inflige un dado adicional de su daño cuando el osgo impacta con ella (incluido en el ataque)."},{"name":"Ataque sorpresa","desc":"Si el osgo sorprende a una criatura y la impacta con un ataque durante el primer asalto del combate, el objetivo recibe 7 (2d6) de daño adicional de ese ataque."}],"actions":[],"reactions":[],"legendary":[]}},"srd:bulette":{"pt-BR":{"lines":[{"label":"Deslocamento","text":"40 ft, escavação 40 ft"},{"label":"Perícias","text":"Percepção +6"},{"label":"Sentidos","text":"visão no escuro 60 ft, sentido sísmico 60 ft, Percepção passiva 16"}],"traits":[{"name":"Salto Parado","desc":"O salto em distância do bulette é de até 30 ft e o salto em altura de até 15 ft, com ou sem corrida."}],"actions":[{"name":"Salto Mortal","desc":"Se o bulette saltar pelo menos 15 ft como parte do seu deslocamento, pode usar esta ação para cair de pé num espaço com uma ou mais criaturas. Cada uma delas deve passar num teste de resistência de Força ou Destreza CD 16 (à escolha do alvo) ou cai e sofre 14 (3d6 + 4) de dano de concussão mais 14 (3d6 + 4) de dano cortante. Se passar, sofre só metade do dano, não cai e é empurrada 5 ft para fora do espaço do bulette, para um espaço desocupado à sua escolha. Se não houver espaço desocupado ao alcance, a criatura cai no espaço do bulette."}],"reactions":[],"legendary":[]},"en":{"lines":[{"label":"Speed","text":"40 ft, burrow 40 ft"},{"label":"Skills","text":"Perception +6"},{"label":"Senses","text":"darkvision 60 ft, tremorsense 60 ft, passive Perception 16"}],"traits":[{"name":"Standing Leap","desc":"The bulette's long jump is up to 30 ft. and its high jump is up to 15 ft., with or without a running start."}],"actions":[{"name":"Deadly Leap","desc":"If the bulette jumps at least 15 ft. as part of its movement, it can then use this action to land on its ft. in a space that contains one or more other creatures. Each of those creatures must succeed on a DC 16 Strength or Dexterity saving throw (target's choice) or be knocked prone and take 14 (3d6 + 4) bludgeoning damage plus 14 (3d6 + 4) slashing damage. On a successful save, the creature takes only half the damage, isn't knocked prone, and is pushed 5 ft. out of the bulette's space into an unoccupied space of the creature's choice. If no unoccupied space is within range, the creature instead falls prone in the bulette's space."}],"reactions":[],"legendary":[]},"es":{"lines":[{"label":"Velocidad","text":"40 ft, excavar 40 ft"},{"label":"Habilidades","text":"Percepción +6"},{"label":"Sentidos","text":"visión en la oscuridad 60 ft, sentido de la vibración 60 ft, Percepción pasiva 16"}],"traits":[{"name":"Salto sin carrerilla","desc":"El salto de longitud del bulette es de hasta 30 ft y el de altura de hasta 15 ft, con o sin carrerilla."}],"actions":[{"name":"Salto mortal","desc":"Si el bulette salta al menos 15 ft como parte de su movimiento, puede usar esta acción para caer de pie en un espacio con una o más criaturas. Cada una debe superar una tirada de salvación de Fuerza o Destreza CD 16 (a elección del objetivo) o queda derribada y recibe 14 (3d6 + 4) de daño contundente más 14 (3d6 + 4) de daño cortante. Si la supera, recibe solo la mitad del daño, no queda derribada y es empujada 5 ft fuera del espacio del bulette, a un espacio desocupado de su elección. Si no hay ningún espacio desocupado al alcance, la criatura cae derribada en el espacio del bulette."}],"reactions":[],"legendary":[]}},"srd:camel":{"pt-BR":{"lines":[{"label":"Deslocamento","text":"50 ft"},{"label":"Testes de resistência","text":"FOR +0, DES +0, CON +0, INT +0, SAB +0, CAR +0"},{"label":"Perícias","text":"Acrobacia +0, Lidar com Animais +0, Arcanismo +0, Atletismo +0, Enganação +0, História +0, Intuição +0, Intimidação +0, Investigação +0, Medicina +0, Natureza +0, Percepção +0, Atuação +0, Persuasão +0, Religião +0, Prestidigitação +0, Furtividade +0, Sobrevivência +0"},{"label":"Sentidos","text":"Percepção passiva 9"}],"traits":[],"actions":[],"reactions":[],"legendary":[]},"en":{"lines":[{"label":"Speed","text":"50 ft"},{"label":"Saving Throws","text":"Str +0, Dex +0, Con +0, Int +0, Wis +0, Cha +0"},{"label":"Skills","text":"Acrobatics +0, Animal Handling +0, Arcana +0, Athletics +0, Deception +0, History +0, Insight +0, Intimidation +0, Investigation +0, Medicine +0, Nature +0, Perception +0, Performance +0, Persuasion +0, Religion +0, Sleight of Hand +0, Stealth +0, Survival +0"},{"label":"Senses","text":"passive Perception 9"}],"traits":[],"actions":[],"reactions":[],"legendary":[]},"es":{"lines":[{"label":"Velocidad","text":"50 ft"},{"label":"Tiradas de salvación","text":"FUE +0, DES +0, CON +0, INT +0, SAB +0, CAR +0"},{"label":"Habilidades","text":"Acrobacias +0, Trato con animales +0, Conocimiento arcano +0, Atletismo +0, Engaño +0, Historia +0, Perspicacia +0, Intimidación +0, Investigación +0, Medicina +0, Naturaleza +0, Percepción +0, Interpretación +0, Persuasión +0, Religión +0, Juego de manos +0, Sigilo +0, Supervivencia +0"},{"label":"Sentidos","text":"Percepción pasiva 9"}],"traits":[],"actions":[],"reactions":[],"legendary":[]}},"srd:cat":{"pt-BR":{"lines":[{"label":"Deslocamento","text":"40 ft, escalada 30 ft"},{"label":"Perícias","text":"Percepção +3, Furtividade +4"},{"label":"Sentidos","text":"Percepção passiva 13"}],"traits":[{"name":"Olfato Aguçado","desc":"O gato tem vantagem em testes de Sabedoria (Percepção) que dependam do olfato."}],"actions":[],"reactions":[],"legendary":[]},"en":{"lines":[{"label":"Speed","text":"40 ft, climb 30 ft"},{"label":"Skills","text":"Perception +3, Stealth +4"},{"label":"Senses","text":"passive Perception 13"}],"traits":[{"name":"Keen Smell","desc":"The cat has advantage on Wisdom (Perception) checks that rely on smell."}],"actions":[],"reactions":[],"legendary":[]},"es":{"lines":[{"label":"Velocidad","text":"40 ft, trepar 30 ft"},{"label":"Habilidades","text":"Percepción +3, Sigilo +4"},{"label":"Sentidos","text":"Percepción pasiva 13"}],"traits":[{"name":"Olfato agudo","desc":"El gato tiene ventaja en las pruebas de Sabiduría (Percepción) que dependan del olfato."}],"actions":[],"reactions":[],"legendary":[]}},"srd:centaur":{"pt-BR":{"lines":[{"label":"Deslocamento","text":"50 ft"},{"label":"Perícias","text":"Atletismo +6, Percepção +3, Sobrevivência +3"},{"label":"Sentidos","text":"Percepção passiva 13"},{"label":"Idiomas","text":"Élfico, Silvestre"}],"traits":[{"name":"Investida","desc":"Se o centauro se mover pelo menos 30 ft em linha reta até um alvo e o acertar com um ataque de pique no mesmo turno, o alvo sofre 10 (3d6) de dano perfurante extra."}],"actions":[{"name":"Ataques Múltiplos","desc":"O centauro faz dois ataques: um com o pique e um com os cascos, ou dois com o arco longo."}],"reactions":[],"legendary":[]},"en":{"lines":[{"label":"Speed","text":"50 ft"},{"label":"Skills","text":"Athletics +6, Perception +3, Survival +3"},{"label":"Senses","text":"passive Perception 13"},{"label":"Languages","text":"Elvish, Sylvan"}],"traits":[{"name":"Charge","desc":"If the centaur moves at least 30 ft. straight toward a target and then hits it with a pike attack on the same turn, the target takes an extra 10 (3d6) piercing damage."}],"actions":[{"name":"Multiattack","desc":"The centaur makes two attacks: one with its pike and one with its hooves or two with its longbow."}],"reactions":[],"legendary":[]},"es":{"lines":[{"label":"Velocidad","text":"50 ft"},{"label":"Habilidades","text":"Atletismo +6, Percepción +3, Supervivencia +3"},{"label":"Sentidos","text":"Percepción pasiva 13"},{"label":"Idiomas","text":"Élfico, silvano"}],"traits":[{"name":"Carga","desc":"Si el centauro se mueve al menos 30 ft en línea recta hacia un objetivo y lo impacta con un ataque de pica en el mismo turno, el objetivo recibe 10 (3d6) de daño perforante adicional."}],"actions":[{"name":"Ataque múltiple","desc":"El centauro hace dos ataques: uno con la pica y otro con los cascos, o dos con el arco largo."}],"reactions":[],"legendary":[]}},"srd:chain-devil":{"pt-BR":{"lines":[{"label":"Deslocamento","text":"30 ft"},{"label":"Testes de resistência","text":"CON +7, SAB +4, CAR +5"},{"label":"Resistência a dano","text":"frio; concussão, perfurante e cortante de ataques não mágicos feitos sem armas de prata"},{"label":"Imunidade a dano","text":"fogo, veneno"},{"label":"Imunidade a condição","text":"envenenado"},{"label":"Sentidos","text":"visão no escuro 120 ft, Percepção passiva 8"},{"label":"Idiomas","text":"Infernal, telepatia 120 ft"}],"traits":[{"name":"Visão do Diabo","desc":"A escuridão mágica não atrapalha a visão no escuro do diabo."},{"name":"Resistência à Magia","desc":"O diabo tem vantagem em testes de resistência contra magias e outros efeitos mágicos."}],"actions":[{"name":"Ataques Múltiplos","desc":"O diabo faz dois ataques com as correntes."},{"name":"Animar Correntes","desc":"Até quatro correntes que o diabo possa ver a até 60 ft dele ganham magicamente farpas afiadas e se animam sob o controle do diabo, desde que ninguém as esteja vestindo ou carregando.\nCada corrente animada é um objeto com CA 20, 20 pontos de vida, resistência a dano perfurante e imunidade a dano psíquico e trovejante. Quando o diabo usa Ataques Múltiplos no seu turno, pode usar cada corrente animada para fazer um ataque de corrente adicional. Uma corrente animada pode agarrar uma criatura, mas não ataca enquanto agarra. Ela volta a ficar inanimada se chegar a 0 pontos de vida ou se o diabo ficar incapacitado ou morrer."}],"reactions":[{"name":"Máscara Perturbadora","desc":"Quando uma criatura que o diabo possa ver começa o turno a até 30 ft dele, o diabo pode criar a ilusão de que se parece com um ente querido falecido ou um inimigo mortal dessa criatura. Se a criatura puder ver o diabo, deve passar num teste de resistência de Sabedoria CD 14 ou fica amedrontada até o fim do seu turno."}],"legendary":[]},"en":{"lines":[{"label":"Speed","text":"30 ft"},{"label":"Saving Throws","text":"Con +7, Wis +4, Cha +5"},{"label":"Damage Resistances","text":"cold; bludgeoning, piercing, and slashing from nonmagical attacks not made with silvered weapons"},{"label":"Damage Immunities","text":"fire, poison"},{"label":"Condition Immunities","text":"poisoned"},{"label":"Senses","text":"darkvision 120 ft, passive Perception 8"},{"label":"Languages","text":"Infernal, telepathy 120 ft."}],"traits":[{"name":"Devil's Sight","desc":"Magical darkness doesn't impede the devil's darkvision."},{"name":"Magic Resistance","desc":"The devil has advantage on saving throws against spells and other magical effects."}],"actions":[{"name":"Multiattack","desc":"The devil makes two attacks with its chains."},{"name":"Animate Chains","desc":"Up to four chains the devil can see within 60 feet of it magically sprout razor-edged barbs and animate under the devil's control, provided that the chains aren't being worn or carried.\nEach animated chain is an object with AC 20, 20 hit points, resistance to piercing damage, and immunity to psychic and thunder damage. When the devil uses Multiattack on its turn, it can use each animated chain to make one additional chain attack. An animated chain can grapple one creature of its own but can't make attacks while grappling. An animated chain reverts to its inanimate state if reduced to 0 hit points or if the devil is incapacitated or dies."}],"reactions":[{"name":"Unnerving Mask","desc":"When a creature the devil can see starts its turn within 30 feet of the devil, the devil can create the illusion that it looks like one of the creature's departed loved ones or bitter enemies. If the creature can see the devil, it must succeed on a DC 14 Wisdom saving throw or be frightened until the end of its turn."}],"legendary":[]},"es":{"lines":[{"label":"Velocidad","text":"30 ft"},{"label":"Tiradas de salvación","text":"CON +7, SAB +4, CAR +5"},{"label":"Resistencias al daño","text":"frío; contundente, perforante y cortante de ataques no mágicos hechos sin armas de plata"},{"label":"Inmunidades al daño","text":"fuego, veneno"},{"label":"Inmunidades a estados","text":"envenenado"},{"label":"Sentidos","text":"visión en la oscuridad 120 ft, Percepción pasiva 8"},{"label":"Idiomas","text":"Infernal, telepatía 120 ft"}],"traits":[{"name":"Vista del diablo","desc":"La oscuridad mágica no impide la visión en la oscuridad del diablo."},{"name":"Resistencia mágica","desc":"El diablo tiene ventaja en las tiradas de salvación contra conjuros y otros efectos mágicos."}],"actions":[{"name":"Ataque múltiple","desc":"El diablo hace dos ataques con las cadenas."},{"name":"Animar cadenas","desc":"Hasta cuatro cadenas que el diablo pueda ver a 60 ft o menos de él se llenan mágicamente de púas afiladas y se animan bajo su control, siempre que nadie las lleve puestas o encima.\nCada cadena animada es un objeto con CA 20, 20 puntos de golpe, resistencia al daño perforante e inmunidad al daño psíquico y de trueno. Cuando el diablo usa Ataque múltiple en su turno, puede usar cada cadena animada para hacer un ataque de cadena adicional. Una cadena animada puede agarrar a una criatura, pero no puede atacar mientras agarra. Vuelve a quedar inanimada si se reduce a 0 puntos de golpe o si el diablo queda incapacitado o muere."}],"reactions":[{"name":"Máscara inquietante","desc":"Cuando una criatura que el diablo pueda ver empieza su turno a 30 ft o menos de él, el diablo puede crear la ilusión de que se parece a un ser querido fallecido o a un enemigo acérrimo de esa criatura. Si la criatura puede ver al diablo, debe superar una tirada de salvación de Sabiduría CD 14 o queda asustada hasta el final de su turno."}],"legendary":[]}},"srd:chimera":{"pt-BR":{"lines":[{"label":"Deslocamento","text":"30 ft, voo 60 ft"},{"label":"Perícias","text":"Percepção +8"},{"label":"Sentidos","text":"visão no escuro 60 ft, Percepção passiva 18"},{"label":"Idiomas","text":"entende Dracônico mas não fala"}],"traits":[],"actions":[{"name":"Ataques Múltiplos","desc":"A quimera faz três ataques: um de mordida, um de chifres e um de garras. Quando o sopro de fogo estiver disponível, pode usá-lo no lugar da mordida ou dos chifres."},{"name":"Sopro de Fogo (recarga 5–6)","desc":"A cabeça de dragão exala fogo num cone de 15 ft. Cada criatura na área deve fazer um teste de resistência de Destreza CD 15; sofre 31 (7d8) de dano de fogo se falhar, ou metade se passar."}],"reactions":[],"legendary":[]},"en":{"lines":[{"label":"Speed","text":"30 ft, fly 60 ft"},{"label":"Skills","text":"Perception +8"},{"label":"Senses","text":"darkvision 60 ft, passive Perception 18"},{"label":"Languages","text":"understands Draconic but can't speak"}],"traits":[],"actions":[{"name":"Multiattack","desc":"The chimera makes three attacks: one with its bite, one with its horns, and one with its claws. When its fire breath is available, it can use the breath in place of its bite or horns."},{"name":"Fire Breath (Recharge 5–6)","desc":"The dragon head exhales fire in a 15-foot cone. Each creature in that area must make a DC 15 Dexterity saving throw, taking 31 (7d8) fire damage on a failed save, or half as much damage on a successful one."}],"reactions":[],"legendary":[]},"es":{"lines":[{"label":"Velocidad","text":"30 ft, volar 60 ft"},{"label":"Habilidades","text":"Percepción +8"},{"label":"Sentidos","text":"visión en la oscuridad 60 ft, Percepción pasiva 18"},{"label":"Idiomas","text":"entiende dracónico pero no lo habla"}],"traits":[],"actions":[{"name":"Ataque múltiple","desc":"La quimera hace tres ataques: uno de mordisco, otro de cuernos y otro de garras. Cuando su aliento de fuego esté disponible, puede usarlo en lugar del mordisco o de los cuernos."},{"name":"Aliento de fuego (recarga 5–6)","desc":"La cabeza de dragón exhala fuego en un cono de 15 ft. Cada criatura en esa área debe hacer una tirada de salvación de Destreza CD 15; recibe 31 (7d8) de daño de fuego si falla, o la mitad si la supera."}],"reactions":[],"legendary":[]}},"srd:chuul":{"pt-BR":{"lines":[{"label":"Deslocamento","text":"30 ft, natação 30 ft"},{"label":"Perícias","text":"Percepção +4"},{"label":"Imunidade a dano","text":"veneno"},{"label":"Imunidade a condição","text":"envenenado"},{"label":"Sentidos","text":"visão no escuro 60 ft, Percepção passiva 14"},{"label":"Idiomas","text":"entende Dialeto das Profundezas mas não fala"}],"traits":[{"name":"Anfíbio","desc":"O chuul pode respirar ar e água."},{"name":"Sentir Magia","desc":"O chuul percebe magia a até 120 ft à vontade. No resto, este traço funciona como a magia detectar magia, mas não é mágico."}],"actions":[{"name":"Ataques Múltiplos","desc":"O chuul faz dois ataques de pinça. Se estiver agarrando uma criatura, também pode usar os tentáculos uma vez."},{"name":"Tentáculos","desc":"Uma criatura agarrada pelo chuul deve passar num teste de resistência de Constituição CD 13 ou fica envenenada por 1 minuto. Enquanto o veneno durar, o alvo fica paralisado. Ele pode repetir o teste ao fim de cada um dos seus turnos, encerrando o efeito em si mesmo se passar."}],"reactions":[],"legendary":[]},"en":{"lines":[{"label":"Speed","text":"30 ft, swim 30 ft"},{"label":"Skills","text":"Perception +4"},{"label":"Damage Immunities","text":"poison"},{"label":"Condition Immunities","text":"poisoned"},{"label":"Senses","text":"darkvision 60 ft, passive Perception 14"},{"label":"Languages","text":"understands Deep Speech but can't speak"}],"traits":[{"name":"Amphibious","desc":"The chuul can breathe air and water."},{"name":"Sense Magic","desc":"The chuul senses magic within 120 feet of it at will. This trait otherwise works like the detect magic spell but isn't itself magical."}],"actions":[{"name":"Multiattack","desc":"The chuul makes two pincer attacks. If the chuul is grappling a creature, the chuul can also use its tentacles once."},{"name":"Tentacles","desc":"One creature grappled by the chuul must succeed on a DC 13 Constitution saving throw or be poisoned for 1 minute. Until this poison ends, the target is paralyzed. The target can repeat the saving throw at the end of each of its turns, ending the effect on itself on a success."}],"reactions":[],"legendary":[]},"es":{"lines":[{"label":"Velocidad","text":"30 ft, nadar 30 ft"},{"label":"Habilidades","text":"Percepción +4"},{"label":"Inmunidades al daño","text":"veneno"},{"label":"Inmunidades a estados","text":"envenenado"},{"label":"Sentidos","text":"visión en la oscuridad 60 ft, Percepción pasiva 14"},{"label":"Idiomas","text":"entiende habla profunda pero no la habla"}],"traits":[{"name":"Anfibio","desc":"El chuul puede respirar aire y agua."},{"name":"Percibir magia","desc":"El chuul percibe la magia a 120 ft o menos a voluntad. Por lo demás, este rasgo funciona como el conjuro detectar magia, pero no es mágico."}],"actions":[{"name":"Ataque múltiple","desc":"El chuul hace dos ataques de pinza. Si está agarrando a una criatura, también puede usar los tentáculos una vez."},{"name":"Tentáculos","desc":"Una criatura agarrada por el chuul debe superar una tirada de salvación de Constitución CD 13 o queda envenenada durante 1 minuto. Mientras dure el veneno, el objetivo está paralizado. Puede repetir la tirada al final de cada uno de sus turnos y termina el efecto sobre sí mismo si la supera."}],"reactions":[],"legendary":[]}},"srd:clay-golem":{"pt-BR":{"lines":[{"label":"Deslocamento","text":"20 ft"},{"label":"Imunidade a dano","text":"ácido, veneno, psíquico; concussão, perfurante e cortante de ataques não mágicos feitos sem armas de adamante"},{"label":"Imunidade a condição","text":"enfeitiçado, exaustão, amedrontado, paralisado, petrificado, envenenado"},{"label":"Sentidos","text":"visão no escuro 60 ft, Percepção passiva 9"},{"label":"Idiomas","text":"entende os idiomas do seu criador mas não fala"}],"traits":[{"name":"Absorção de Ácido","desc":"Sempre que o golem sofreria dano de ácido, ele não sofre o dano e recupera pontos de vida iguais ao dano de ácido causado."},{"name":"Fúria Desenfreada","desc":"Sempre que o golem começar o turno com 60 pontos de vida ou menos, role um d6. Num 6, o golem entra em fúria. Em cada um dos seus turnos em fúria, ataca a criatura mais próxima que possa ver. Se nenhuma estiver perto o bastante para se mover até ela e atacar, ataca um objeto, de preferência menor que ele. Depois que entra em fúria, continua assim até ser destruído ou recuperar todos os pontos de vida."},{"name":"Forma Imutável","desc":"O golem é imune a qualquer magia ou efeito que alteraria sua forma."},{"name":"Resistência à Magia","desc":"O golem tem vantagem em testes de resistência contra magias e outros efeitos mágicos."},{"name":"Armas Mágicas","desc":"Os ataques com arma do golem são mágicos."}],"actions":[{"name":"Ataques Múltiplos","desc":"O golem faz dois ataques de pancada."},{"name":"Velocidade","desc":"Até o fim do seu próximo turno, o golem ganha magicamente +2 na CA, tem vantagem em testes de resistência de Destreza e pode usar o ataque de pancada como ação bônus."}],"reactions":[],"legendary":[]},"en":{"lines":[{"label":"Speed","text":"20 ft"},{"label":"Damage Immunities","text":"acid, poison, psychic; bludgeoning, piercing, and slashing from nonmagical attacks not made with adamantine weapons"},{"label":"Condition Immunities","text":"charmed, exhaustion, frightened, paralyzed, petrified, poisoned"},{"label":"Senses","text":"darkvision 60 ft, passive Perception 9"},{"label":"Languages","text":"understands the languages of its creator but can't speak"}],"traits":[{"name":"Acid Absorption","desc":"Whenever the golem is subjected to acid damage, it takes no damage and instead regains a number of hit points equal to the acid damage dealt."},{"name":"Berserk","desc":"Whenever the golem starts its turn with 60 hit points or fewer, roll a d6. On a 6, the golem goes berserk. On each of its turns while berserk, the golem attacks the nearest creature it can see. If no creature is near enough to move to and attack, the golem attacks an object, with preference for an object smaller than itself. Once the golem goes berserk, it continues to do so until it is destroyed or regains all its hit points."},{"name":"Immutable Form","desc":"The golem is immune to any spell or effect that would alter its form."},{"name":"Magic Resistance","desc":"The golem has advantage on saving throws against spells and other magical effects."},{"name":"Magic Weapons","desc":"The golem's weapon attacks are magical."}],"actions":[{"name":"Multiattack","desc":"The golem makes two slam attacks."},{"name":"Haste","desc":"Until the end of its next turn, the golem magically gains a +2 bonus to its AC, has advantage on Dexterity saving throws, and can use its slam attack as a bonus action."}],"reactions":[],"legendary":[]},"es":{"lines":[{"label":"Velocidad","text":"20 ft"},{"label":"Inmunidades al daño","text":"ácido, veneno, psíquico; contundente, perforante y cortante de ataques no mágicos hechos sin armas de adamantina"},{"label":"Inmunidades a estados","text":"hechizado, agotamiento, asustado, paralizado, petrificado, envenenado"},{"label":"Sentidos","text":"visión en la oscuridad 60 ft, Percepción pasiva 9"},{"label":"Idiomas","text":"entiende los idiomas de su creador pero no habla"}],"traits":[{"name":"Absorción de ácido","desc":"Cada vez que el golem fuera a recibir daño de ácido, no recibe el daño y recupera tantos puntos de golpe como el daño de ácido infligido."},{"name":"Enloquecido","desc":"Cada vez que el gólem empiece su turno con 60 puntos de golpe o menos, tira un d6. Con un 6, el gólem enloquece. En cada uno de sus turnos mientras está enloquecido, ataca a la criatura más cercana que pueda ver. Si ninguna está lo bastante cerca para moverse hasta ella y atacarla, ataca un objeto, preferiblemente más pequeño que él. Una vez enloquece, sigue así hasta ser destruido o recuperar todos sus puntos de golpe."},{"name":"Forma inmutable","desc":"El gólem es inmune a cualquier conjuro o efecto que fuera a alterar su forma."},{"name":"Resistencia mágica","desc":"El gólem tiene ventaja en las tiradas de salvación contra conjuros y otros efectos mágicos."},{"name":"Armas mágicas","desc":"Los ataques con arma del gólem son mágicos."}],"actions":[{"name":"Ataque múltiple","desc":"El gólem hace dos ataques de golpe."},{"name":"Celeridad","desc":"Hasta el final de su siguiente turno, el gólem obtiene mágicamente un +2 a la CA, tiene ventaja en las tiradas de salvación de Destreza y puede usar su ataque de golpe como acción adicional."}],"reactions":[],"legendary":[]}},"srd:cloaker":{"pt-BR":{"lines":[{"label":"Deslocamento","text":"10 ft, voo 40 ft"},{"label":"Perícias","text":"Furtividade +5"},{"label":"Sentidos","text":"visão no escuro 60 ft, Percepção passiva 11"},{"label":"Idiomas","text":"Dialeto das Profundezas, Dialeto Subterrâneo"}],"traits":[{"name":"Transferência de Dano","desc":"Enquanto estiver preso a uma criatura, a capa assassina sofre só metade do dano que recebe (arredondado para baixo), e essa criatura sofre a outra metade."},{"name":"Falsa Aparência","desc":"Enquanto fica imóvel e sem mostrar a parte de baixo, a capa assassina é indistinguível de uma capa de couro escuro."},{"name":"Sensibilidade à Luz","desc":"Sob luz plena, a capa assassina tem desvantagem nas jogadas de ataque e nos testes de Sabedoria (Percepção) que dependam da visão."}],"actions":[{"name":"Ataques Múltiplos","desc":"A capa assassina faz dois ataques: um de mordida e um de cauda."},{"name":"Gemido","desc":"Cada criatura a até 60 ft da capa assassina que possa ouvir o gemido e que não seja uma aberração deve passar num teste de resistência de Sabedoria CD 13 ou fica amedrontada até o fim do próximo turno da capa. Se passar, fica imune ao gemido da capa assassina pelas próximas 24 horas."},{"name":"Fantasmas","desc":"A capa assassina cria magicamente três cópias ilusórias de si mesma, se não estiver sob luz plena. As cópias se movem com ela e imitam suas ações, trocando de posição para que seja impossível saber qual é a verdadeira. Se a capa entrar numa área de luz plena, as cópias somem.\nSempre que uma criatura tenta atingir a capa com um ataque ou magia nociva enquanto restar alguma cópia, ela rola aleatoriamente para saber se mira a capa ou uma das cópias. Uma criatura que não enxerga ou que depende de outros sentidos que não a visão não é afetada por este efeito mágico.\nCada cópia tem a CA da capa e usa os testes de resistência dela. Se um ataque acertar uma cópia, ou se uma cópia falhar num teste de resistência contra um efeito que cause dano, ela some."}],"reactions":[],"legendary":[]},"en":{"lines":[{"label":"Speed","text":"10 ft, fly 40 ft"},{"label":"Skills","text":"Stealth +5"},{"label":"Senses","text":"darkvision 60 ft, passive Perception 11"},{"label":"Languages","text":"Deep Speech, Undercommon"}],"traits":[{"name":"Damage Transfer","desc":"While attached to a creature, the cloaker takes only half the damage dealt to it (rounded down). and that creature takes the other half."},{"name":"False Appearance","desc":"While the cloaker remains motionless without its underside exposed, it is indistinguishable from a dark leather cloak."},{"name":"Light Sensitivity","desc":"While in bright light, the cloaker has disadvantage on attack rolls and Wisdom (Perception) checks that rely on sight."}],"actions":[{"name":"Multiattack","desc":"The cloaker makes two attacks: one with its bite and one with its tail."},{"name":"Moan","desc":"Each creature within 60 feet of the cloaker that can hear its moan and that isn't an aberration must succeed on a DC 13 Wisdom saving throw or become frightened until the end of the cloaker's next turn. If a creature's saving throw is successful, the creature is immune to the cloaker's moan for the next 24 hours."},{"name":"Phantasms","desc":"The cloaker magically creates three illusory duplicates of itself if it isn't in bright light. The duplicates move with it and mimic its actions, shifting position so as to make it impossible to track which cloaker is the real one. If the cloaker is ever in an area of bright light, the duplicates disappear.\nWhenever any creature targets the cloaker with an attack or a harmful spell while a duplicate remains, that creature rolls randomly to determine whether it targets the cloaker or one of the duplicates. A creature is unaffected by this magical effect if it can't see or if it relies on senses other than sight.\nA duplicate has the cloaker's AC and uses its saving throws. If an attack hits a duplicate, or if a duplicate fails a saving throw against an effect that deals damage, the duplicate disappears."}],"reactions":[],"legendary":[]},"es":{"lines":[{"label":"Velocidad","text":"10 ft, volar 40 ft"},{"label":"Habilidades","text":"Sigilo +5"},{"label":"Sentidos","text":"visión en la oscuridad 60 ft, Percepción pasiva 11"},{"label":"Idiomas","text":"Habla profunda, infracomún"}],"traits":[{"name":"Transferencia de daño","desc":"Mientras está adherido a una criatura, el acechador embozado recibe solo la mitad del daño que le infligen (redondeando hacia abajo), y esa criatura recibe la otra mitad."},{"name":"Apariencia falsa","desc":"Mientras permanece inmóvil y sin mostrar su parte inferior, el acechador embozado es indistinguible de una capa de cuero oscuro."},{"name":"Sensibilidad a la luz","desc":"Bajo luz brillante, el acechador embozado tiene desventaja en las tiradas de ataque y en las pruebas de Sabiduría (Percepción) que dependan de la vista."}],"actions":[{"name":"Ataque múltiple","desc":"El acechador embozado hace dos ataques: uno de mordisco y otro de cola."},{"name":"Gemido","desc":"Cada criatura a 60 ft o menos del acechador embozado que pueda oír su gemido y que no sea una aberración debe superar una tirada de salvación de Sabiduría CD 13 o queda asustada hasta el final del siguiente turno del acechador. Si la supera, es inmune al gemido del acechador embozado durante las siguientes 24 horas."},{"name":"Fantasmas","desc":"El acechador embozado crea mágicamente tres duplicados ilusorios de sí mismo, si no está bajo luz brillante. Los duplicados se mueven con él e imitan sus acciones, cambiando de posición para que sea imposible saber cuál es el verdadero. Si el acechador entra en un área de luz brillante, los duplicados desaparecen.\nCada vez que una criatura elige como objetivo al acechador con un ataque o un conjuro dañino mientras quede algún duplicado, tira al azar para ver si apunta al acechador o a uno de los duplicados. Una criatura que no puede ver o que depende de sentidos distintos de la vista no se ve afectada por este efecto mágico.\nCada duplicado tiene la CA del acechador y usa sus tiradas de salvación. Si un ataque impacta a un duplicado, o si un duplicado falla una tirada de salvación contra un efecto que inflige daño, desaparece."}],"reactions":[],"legendary":[]}},"srd:cloud-giant":{"pt-BR":{"lines":[{"label":"Deslocamento","text":"40 ft"},{"label":"Testes de resistência","text":"CON +10, SAB +7, CAR +7"},{"label":"Perícias","text":"Intuição +7, Percepção +7"},{"label":"Sentidos","text":"Percepção passiva 17"},{"label":"Idiomas","text":"Comum, Gigante"}],"traits":[{"name":"Conjuração Inata","desc":"A habilidade de conjuração inata do gigante é Carisma. Ele pode conjurar as seguintes magias, sem precisar de componentes materiais:\n\nÀ vontade: detectar magia, névoa obscurecente, luz\n3/dia cada: queda suave, voo, passo nebuloso, telecinésia\n1/dia cada: controlar o clima, forma gasosa"},{"name":"Olfato Aguçado","desc":"O gigante tem vantagem em testes de Sabedoria (Percepção) que dependam do olfato."}],"actions":[{"name":"Ataques Múltiplos","desc":"O gigante faz dois ataques de maça-estrela."}],"reactions":[],"legendary":[]},"en":{"lines":[{"label":"Speed","text":"40 ft"},{"label":"Saving Throws","text":"Con +10, Wis +7, Cha +7"},{"label":"Skills","text":"Insight +7, Perception +7"},{"label":"Senses","text":"passive Perception 17"},{"label":"Languages","text":"Common, Giant"}],"traits":[{"name":"Innate Spellcasting","desc":"The giant's innate spellcasting ability is Charisma. It can innately cast the following spells, requiring no material components:\n\nAt will: detect magic, fog cloud, light\n3/day each: feather fall, fly, misty step, telekinesis\n1/day each: control weather, gaseous form"},{"name":"Keen Smell","desc":"The giant has advantage on Wisdom (Perception) checks that rely on smell."}],"actions":[{"name":"Multiattack","desc":"The giant makes two morningstar attacks."}],"reactions":[],"legendary":[]},"es":{"lines":[{"label":"Velocidad","text":"40 ft"},{"label":"Tiradas de salvación","text":"CON +10, SAB +7, CAR +7"},{"label":"Habilidades","text":"Perspicacia +7, Percepción +7"},{"label":"Sentidos","text":"Percepción pasiva 17"},{"label":"Idiomas","text":"Común, gigante"}],"traits":[{"name":"Lanzamiento de conjuros innato","desc":"La aptitud mágica innata del gigante es Carisma. Puede lanzar los siguientes conjuros sin necesidad de componentes materiales:\n\nA voluntad: detectar magia, nube de niebla, luz\n3/día cada uno: caída de pluma, volar, paso brumoso, telequinesis\n1/día cada uno: controlar el clima, forma gaseosa"},{"name":"Olfato agudo","desc":"El gigante tiene ventaja en las pruebas de Sabiduría (Percepción) que dependan del olfato."}],"actions":[{"name":"Ataque múltiple","desc":"El gigante hace dos ataques de lucero del alba."}],"reactions":[],"legendary":[]}},"srd:cockatrice":{"pt-BR":{"lines":[{"label":"Deslocamento","text":"20 ft, voo 40 ft"},{"label":"Sentidos","text":"visão no escuro 60 ft, Percepção passiva 11"}],"traits":[],"actions":[],"reactions":[],"legendary":[]},"en":{"lines":[{"label":"Speed","text":"20 ft, fly 40 ft"},{"label":"Senses","text":"darkvision 60 ft, passive Perception 11"}],"traits":[],"actions":[],"reactions":[],"legendary":[]},"es":{"lines":[{"label":"Velocidad","text":"20 ft, volar 40 ft"},{"label":"Sentidos","text":"visión en la oscuridad 60 ft, Percepción pasiva 11"}],"traits":[],"actions":[],"reactions":[],"legendary":[]}},"srd:commoner":{"pt-BR":{"lines":[{"label":"Deslocamento","text":"30 ft"},{"label":"Sentidos","text":"Percepção passiva 10"},{"label":"Idiomas","text":"um idioma qualquer (geralmente Comum)"}],"traits":[],"actions":[],"reactions":[],"legendary":[]},"en":{"lines":[{"label":"Speed","text":"30 ft"},{"label":"Senses","text":"passive Perception 10"},{"label":"Languages","text":"any one language (usually Common)"}],"traits":[],"actions":[],"reactions":[],"legendary":[]},"es":{"lines":[{"label":"Velocidad","text":"30 ft"},{"label":"Sentidos","text":"Percepción pasiva 10"},{"label":"Idiomas","text":"un idioma cualquiera (normalmente común)"}],"traits":[],"actions":[],"reactions":[],"legendary":[]}},"srd:constrictor-snake":{"pt-BR":{"lines":[{"label":"Deslocamento","text":"30 ft, natação 30 ft"},{"label":"Sentidos","text":"percepção às cegas 10 ft, Percepção passiva 10"}],"traits":[],"actions":[],"reactions":[],"legendary":[]},"en":{"lines":[{"label":"Speed","text":"30 ft, swim 30 ft"},{"label":"Senses","text":"blindsight 10 ft, passive Perception 10"}],"traits":[],"actions":[],"reactions":[],"legendary":[]},"es":{"lines":[{"label":"Velocidad","text":"30 ft, nadar 30 ft"},{"label":"Sentidos","text":"vista ciega 10 ft, Percepción pasiva 10"}],"traits":[],"actions":[],"reactions":[],"legendary":[]}},"srd:couatl":{"pt-BR":{"lines":[{"label":"Deslocamento","text":"30 ft, voo 90 ft"},{"label":"Testes de resistência","text":"CON +5, SAB +7, CAR +6"},{"label":"Resistência a dano","text":"radiante"},{"label":"Imunidade a dano","text":"psíquico; concussão, perfurante e cortante de ataques não mágicos"},{"label":"Sentidos","text":"visão verdadeira 120 ft, Percepção passiva 15"},{"label":"Idiomas","text":"todos, telepatia 120 ft"}],"traits":[{"name":"Conjuração Inata","desc":"A habilidade de conjuração do couatl é Carisma (CD de resistência de magia 14). Ele pode conjurar as seguintes magias de forma inata, precisando só de componentes verbais:\n\nÀ vontade: detectar o bem e o mal, detectar magia, detectar pensamentos\n3/dia cada: bênção, criar alimentos e água, curar ferimentos, restauração menor, proteção contra veneno, santuário, escudo arcano\n1/dia cada: sonho, restauração maior, vidência"},{"name":"Armas Mágicas","desc":"Os ataques com arma do couatl são mágicos."},{"name":"Mente Protegida","desc":"O couatl é imune a vidência e a qualquer efeito que perceba suas emoções, leia seus pensamentos ou detecte sua localização."}],"actions":[{"name":"Mudar de Forma","desc":"O couatl se metamorfoseia magicamente num humanoide ou fera com nível de desafio igual ou menor que o seu, ou volta à forma verdadeira. Volta à forma verdadeira se morrer. O equipamento que veste ou carrega é absorvido ou levado pela nova forma (à sua escolha).\nNa nova forma, mantém suas estatísticas de jogo e a capacidade de falar, mas a CA, os modos de deslocamento, Força, Destreza e as outras ações são substituídos pelos da nova forma, e ganha as estatísticas e capacidades (exceto características de classe, ações lendárias e ações de covil) que a nova forma tem e que lhe faltam."}],"reactions":[],"legendary":[]},"en":{"lines":[{"label":"Speed","text":"30 ft, fly 90 ft"},{"label":"Saving Throws","text":"Con +5, Wis +7, Cha +6"},{"label":"Damage Resistances","text":"radiant"},{"label":"Damage Immunities","text":"psychic; bludgeoning, piercing, and slashing from nonmagical attacks"},{"label":"Senses","text":"truesight 120 ft, passive Perception 15"},{"label":"Languages","text":"all, telepathy 120 ft."}],"traits":[{"name":"Innate Spellcasting","desc":"The couatl's spellcasting ability is Charisma (spell save DC 14). It can innately cast the following spells, requiring only verbal components:\n\nAt will: detect evil and good, detect magic, detect thoughts\n3/day each: bless, create food and water, cure wounds, lesser restoration, protection from poison, sanctuary, shield\n1/day each: dream, greater restoration, scrying"},{"name":"Magic Weapons","desc":"The couatl's weapon attacks are magical."},{"name":"Shielded Mind","desc":"The couatl is immune to scrying and to any effect that would sense its emotions, read its thoughts, or detect its location."}],"actions":[{"name":"Change Shape","desc":"The couatl magically polymorphs into a humanoid or beast that has a challenge rating equal to or less than its own, or back into its true form. It reverts to its true form if it dies. Any equipment it is wearing or carrying is absorbed or borne by the new form (the couatl's choice).\nIn a new form, the couatl retains its game statistics and ability to speak, but its AC, movement modes, Strength, Dexterity, and other actions are replaced by those of the new form, and it gains any statistics and capabilities (except class features, legendary actions, and lair actions) that the new form has but that it lacks. If the new form has a bite attack, the couatl can use its bite in that form."}],"reactions":[],"legendary":[]},"es":{"lines":[{"label":"Velocidad","text":"30 ft, volar 90 ft"},{"label":"Tiradas de salvación","text":"CON +5, SAB +7, CAR +6"},{"label":"Resistencias al daño","text":"radiante"},{"label":"Inmunidades al daño","text":"psíquico; contundente, perforante y cortante de ataques no mágicos"},{"label":"Sentidos","text":"visión verdadera 120 ft, Percepción pasiva 15"},{"label":"Idiomas","text":"todos, telepatía 120 ft"}],"traits":[{"name":"Lanzamiento de conjuros innato","desc":"La aptitud mágica del couatl es Carisma (CD de salvación de conjuros 14). Puede lanzar de forma innata los siguientes conjuros, necesitando solo componentes verbales:\n\nA voluntad: detectar el bien y el mal, detectar magia, detectar pensamientos\n3/día cada uno: bendición, crear comida y agua, curar heridas, restablecimiento menor, protección contra el veneno, santuario, escudo\n1/día cada uno: sueño, restablecimiento mayor, escudriñar"},{"name":"Armas mágicas","desc":"Los ataques con arma del couatl son mágicos."},{"name":"Mente protegida","desc":"El couatl es inmune a escudriñar y a cualquier efecto que perciba sus emociones, lea sus pensamientos o detecte su ubicación."}],"actions":[{"name":"Cambiar de forma","desc":"El couatl se polimorfa mágicamente en un humanoide o bestia con un valor de desafío igual o inferior al suyo, o vuelve a su forma verdadera. Vuelve a su forma verdadera si muere. El equipo que lleve puesto o encima es absorbido o portado por la nueva forma (a su elección).\nEn la nueva forma conserva sus estadísticas de juego y la capacidad de hablar, pero su CA, sus modos de movimiento, Fuerza, Destreza y sus demás acciones se sustituyen por los de la nueva forma, y obtiene las estadísticas y capacidades (salvo rasgos de clase, acciones legendarias y acciones de guarida) que la nueva forma tenga y a él le falten."}],"reactions":[],"legendary":[]}},"srd:crab":{"pt-BR":{"lines":[{"label":"Deslocamento","text":"20 ft, natação 20 ft"},{"label":"Perícias","text":"Furtividade +2"},{"label":"Sentidos","text":"percepção às cegas 30 ft, Percepção passiva 9"}],"traits":[{"name":"Anfíbio","desc":"O caranguejo pode respirar ar e água."}],"actions":[],"reactions":[],"legendary":[]},"en":{"lines":[{"label":"Speed","text":"20 ft, swim 20 ft"},{"label":"Skills","text":"Stealth +2"},{"label":"Senses","text":"blindsight 30 ft, passive Perception 9"}],"traits":[{"name":"Amphibious","desc":"The crab can breathe air and water."}],"actions":[],"reactions":[],"legendary":[]},"es":{"lines":[{"label":"Velocidad","text":"20 ft, nadar 20 ft"},{"label":"Habilidades","text":"Sigilo +2"},{"label":"Sentidos","text":"vista ciega 30 ft, Percepción pasiva 9"}],"traits":[{"name":"Anfibio","desc":"El cangrejo puede respirar aire y agua."}],"actions":[],"reactions":[],"legendary":[]}},"srd:crocodile":{"pt-BR":{"lines":[{"label":"Deslocamento","text":"20 ft, natação 20 ft"},{"label":"Perícias","text":"Furtividade +2"},{"label":"Sentidos","text":"Percepção passiva 10"}],"traits":[{"name":"Prender a Respiração","desc":"O crocodilo pode prender a respiração por 15 minutos."}],"actions":[],"reactions":[],"legendary":[]},"en":{"lines":[{"label":"Speed","text":"20 ft, swim 20 ft"},{"label":"Skills","text":"Stealth +2"},{"label":"Senses","text":"passive Perception 10"}],"traits":[{"name":"Hold Breath","desc":"The crocodile can hold its breath for 15 minutes."}],"actions":[],"reactions":[],"legendary":[]},"es":{"lines":[{"label":"Velocidad","text":"20 ft, nadar 20 ft"},{"label":"Habilidades","text":"Sigilo +2"},{"label":"Sentidos","text":"Percepción pasiva 10"}],"traits":[{"name":"Contener la respiración","desc":"El cocodrilo puede contener la respiración durante 15 minutos."}],"actions":[],"reactions":[],"legendary":[]}},"srd:cult-fanatic":{"pt-BR":{"lines":[{"label":"Deslocamento","text":"30 ft"},{"label":"Perícias","text":"Enganação +4, Persuasão +4, Religião +2"},{"label":"Sentidos","text":"Percepção passiva 11"},{"label":"Idiomas","text":"um idioma qualquer (geralmente Comum)"}],"traits":[{"name":"Devoção Sombria","desc":"O fanático tem vantagem em testes de resistência contra ficar enfeitiçado ou amedrontado."},{"name":"Conjuração","desc":"O fanático é um conjurador de 4º nível. Sua habilidade de conjuração é Sabedoria (CD de resistência de magia 11, +3 para acertar com ataques de magia). O fanático tem as seguintes magias de clérigo preparadas:\n\n* Truques (à vontade): luz, chama sagrada, taumaturgia\n* 1º nível (4 espaços): comando, infligir ferimentos, escudo da fé\n* 2º nível (3 espaços): imobilizar pessoa, arma espiritual"}],"actions":[{"name":"Ataques Múltiplos","desc":"O fanático faz dois ataques corpo a corpo."}],"reactions":[],"legendary":[]},"en":{"lines":[{"label":"Speed","text":"30 ft"},{"label":"Skills","text":"Deception +4, Persuasion +4, Religion +2"},{"label":"Senses","text":"passive Perception 11"},{"label":"Languages","text":"any one language (usually Common)"}],"traits":[{"name":"Dark Devotion","desc":"The fanatic has advantage on saving throws against being charmed or frightened."},{"name":"Spellcasting","desc":"The fanatic is a 4th-level spellcaster. Its spell casting ability is Wisdom (spell save DC 11, +3 to hit with spell attacks). The fanatic has the following cleric spells prepared:\n\nCantrips (at will): light, sacred flame, thaumaturgy\n* 1st level (4 slots): command, inflict wounds, shield of faith\n* 2nd level (3 slots): hold person, spiritual weapon"}],"actions":[{"name":"Multiattack","desc":"The fanatic makes two melee attacks."}],"reactions":[],"legendary":[]},"es":{"lines":[{"label":"Velocidad","text":"30 ft"},{"label":"Habilidades","text":"Engaño +4, Persuasión +4, Religión +2"},{"label":"Sentidos","text":"Percepción pasiva 11"},{"label":"Idiomas","text":"un idioma cualquiera (normalmente común)"}],"traits":[{"name":"Devoción oscura","desc":"El fanático tiene ventaja en las tiradas de salvación para no quedar hechizado ni asustado."},{"name":"Lanzamiento de conjuros","desc":"El fanático es un lanzador de conjuros de nivel 4. Su aptitud mágica es Sabiduría (CD de salvación de conjuros 11, +3 al ataque con conjuros). El fanático tiene preparados los siguientes conjuros de clérigo:\n\n* Trucos (a voluntad): luz, llama sagrada, taumaturgia\n* Nivel 1 (4 espacios): orden imperiosa, infligir heridas, escudo de fe\n* Nivel 2 (3 espacios): inmovilizar persona, arma espiritual"}],"actions":[{"name":"Ataque múltiple","desc":"El fanático hace dos ataques cuerpo a cuerpo."}],"reactions":[],"legendary":[]}},"srd:cultist":{"pt-BR":{"lines":[{"label":"Deslocamento","text":"30 ft"},{"label":"Perícias","text":"Enganação +2, Religião +2"},{"label":"Sentidos","text":"Percepção passiva 10"},{"label":"Idiomas","text":"um idioma qualquer (geralmente Comum)"}],"traits":[{"name":"Devoção Sombria","desc":"O cultista tem vantagem em testes de resistência contra ficar enfeitiçado ou amedrontado."}],"actions":[],"reactions":[],"legendary":[]},"en":{"lines":[{"label":"Speed","text":"30 ft"},{"label":"Skills","text":"Deception +2, Religion +2"},{"label":"Senses","text":"passive Perception 10"},{"label":"Languages","text":"any one language (usually Common)"}],"traits":[{"name":"Dark Devotion","desc":"The cultist has advantage on saving throws against being charmed or frightened."}],"actions":[],"reactions":[],"legendary":[]},"es":{"lines":[{"label":"Velocidad","text":"30 ft"},{"label":"Habilidades","text":"Engaño +2, Religión +2"},{"label":"Sentidos","text":"Percepción pasiva 10"},{"label":"Idiomas","text":"un idioma cualquiera (normalmente común)"}],"traits":[{"name":"Devoción oscura","desc":"El sectario tiene ventaja en las tiradas de salvación para no quedar hechizado ni asustado."}],"actions":[],"reactions":[],"legendary":[]}},"srd:darkmantle":{"pt-BR":{"lines":[{"label":"Deslocamento","text":"10 ft, voo 30 ft"},{"label":"Perícias","text":"Furtividade +3"},{"label":"Sentidos","text":"percepção às cegas 60 ft, Percepção passiva 10"}],"traits":[{"name":"Ecolocalização","desc":"O manto sombrio não pode usar a percepção às cegas enquanto estiver surdo."},{"name":"Falsa Aparência","desc":"Enquanto fica imóvel, o manto sombrio é indistinguível de uma formação de caverna, como uma estalactite ou estalagmite."}],"actions":[{"name":"Aura de Escuridão (1/dia)","desc":"Uma escuridão mágica de 15 ft de raio se espalha a partir do manto sombrio, se move com ele e contorna esquinas. Ela dura enquanto o manto mantiver a concentração, até 10 minutos (como se concentrasse numa magia). A visão no escuro não atravessa essa escuridão, e nenhuma luz natural a ilumina. Se parte da escuridão se sobrepuser a uma área de luz criada por uma magia de 2º nível ou menor, a magia que cria a luz é dissipada."}],"reactions":[],"legendary":[]},"en":{"lines":[{"label":"Speed","text":"10 ft, fly 30 ft"},{"label":"Skills","text":"Stealth +3"},{"label":"Senses","text":"blindsight 60 ft, passive Perception 10"}],"traits":[{"name":"Echolocation","desc":"The darkmantle can't use its blindsight while deafened."},{"name":"False Appearance","desc":"While the darkmantle remains motionless, it is indistinguishable from a cave formation such as a stalactite or stalagmite."}],"actions":[{"name":"Darkness Aura (1/Day)","desc":"A 15-foot radius of magical darkness extends out from the darkmantle, moves with it, and spreads around corners. The darkness lasts as long as the darkmantle maintains concentration, up to 10 minutes (as if concentrating on a spell). Darkvision can't penetrate this darkness, and no natural light can illuminate it. If any of the darkness overlaps with an area of light created by a spell of 2nd level or lower, the spell creating the light is dispelled."}],"reactions":[],"legendary":[]},"es":{"lines":[{"label":"Velocidad","text":"10 ft, volar 30 ft"},{"label":"Habilidades","text":"Sigilo +3"},{"label":"Sentidos","text":"vista ciega 60 ft, Percepción pasiva 10"}],"traits":[{"name":"Ecolocalización","desc":"El manto oscuro no puede usar su vista ciega mientras esté ensordecido."},{"name":"Apariencia falsa","desc":"Mientras permanece inmóvil, el manto oscuro es indistinguible de una formación de cueva, como una estalactita o una estalagmita."}],"actions":[{"name":"Aura de oscuridad (1/día)","desc":"Una oscuridad mágica de 15 ft de radio se extiende desde el manto oscuro, se mueve con él y dobla las esquinas. Dura mientras el manto mantenga la concentración, hasta 10 minutos (como si se concentrara en un conjuro). La visión en la oscuridad no atraviesa esta oscuridad, y ninguna luz natural la ilumina. Si parte de la oscuridad se solapa con un área de luz creada por un conjuro de nivel 2 o inferior, el conjuro que crea la luz se disipa."}],"reactions":[],"legendary":[]}},"srd:death-dog":{"pt-BR":{"lines":[{"label":"Deslocamento","text":"40 ft"},{"label":"Perícias","text":"Percepção +5, Furtividade +4"},{"label":"Sentidos","text":"visão no escuro 120 ft, Percepção passiva 15"}],"traits":[{"name":"Duas Cabeças","desc":"O cão tem vantagem em testes de Sabedoria (Percepção) e em testes de resistência contra ficar cego, enfeitiçado, surdo, amedrontado, atordoado ou inconsciente."}],"actions":[{"name":"Ataques Múltiplos","desc":"O cão faz dois ataques de mordida."}],"reactions":[],"legendary":[]},"en":{"lines":[{"label":"Speed","text":"40 ft"},{"label":"Skills","text":"Perception +5, Stealth +4"},{"label":"Senses","text":"darkvision 120 ft, passive Perception 15"}],"traits":[{"name":"Two-Headed","desc":"The dog has advantage on Wisdom (Perception) checks and on saving throws against being blinded, charmed, deafened, frightened, stunned, or knocked unconscious."}],"actions":[{"name":"Multiattack","desc":"The dog makes two bite attacks."}],"reactions":[],"legendary":[]},"es":{"lines":[{"label":"Velocidad","text":"40 ft"},{"label":"Habilidades","text":"Percepción +5, Sigilo +4"},{"label":"Sentidos","text":"visión en la oscuridad 120 ft, Percepción pasiva 15"}],"traits":[{"name":"Dos cabezas","desc":"El perro tiene ventaja en las pruebas de Sabiduría (Percepción) y en las tiradas de salvación para no quedar cegado, hechizado, ensordecido, asustado, aturdido o inconsciente."}],"actions":[{"name":"Ataque múltiple","desc":"El perro hace dos ataques de mordisco."}],"reactions":[],"legendary":[]}},"srd:deep-gnome-svirfneblin":{"pt-BR":{"lines":[{"label":"Deslocamento","text":"20 ft"},{"label":"Perícias","text":"Investigação +3, Percepção +2, Furtividade +4"},{"label":"Sentidos","text":"visão no escuro 120 ft, Percepção passiva 12"},{"label":"Idiomas","text":"Gnômico, Terran, Dialeto Subterrâneo"}],"traits":[{"name":"Astúcia Gnômica","desc":"O gnomo tem vantagem em testes de resistência de Inteligência, Sabedoria e Carisma contra magia."},{"name":"Conjuração Inata","desc":"A habilidade de conjuração inata do gnomo é Inteligência (CD de resistência de magia 11). Ele pode conjurar as seguintes magias, sem precisar de componentes materiais:\nÀ vontade: indetectável (só em si mesmo)\n1/dia cada: cegueira/surdez, nublar, disfarçar-se"},{"name":"Camuflagem de Pedra","desc":"O gnomo tem vantagem em testes de Destreza (Furtividade) para se esconder em terreno rochoso."}],"actions":[],"reactions":[],"legendary":[]},"en":{"lines":[{"label":"Speed","text":"20 ft"},{"label":"Skills","text":"Investigation +3, Perception +2, Stealth +4"},{"label":"Senses","text":"darkvision 120 ft, passive Perception 12"},{"label":"Languages","text":"Gnomish, Terran, Undercommon"}],"traits":[{"name":"Gnome Cunning","desc":"The gnome has advantage on Intelligence, Wisdom, and Charisma saving throws against magic."},{"name":"Innate Spellcasting","desc":"The gnome's innate spellcasting ability is Intelligence (spell save DC 11). It can innately cast the following spells, requiring no material components:\nAt will: nondetection (self only)\n1/day each: blindness/deafness, blur, disguise self"},{"name":"Stone Camouflage","desc":"The gnome has advantage on Dexterity (Stealth) checks made to hide in rocky terrain."}],"actions":[],"reactions":[],"legendary":[]},"es":{"lines":[{"label":"Velocidad","text":"20 ft"},{"label":"Habilidades","text":"Investigación +3, Percepción +2, Sigilo +4"},{"label":"Sentidos","text":"visión en la oscuridad 120 ft, Percepción pasiva 12"},{"label":"Idiomas","text":"Gnómico, terrano, infracomún"}],"traits":[{"name":"Astucia gnómica","desc":"El gnomo tiene ventaja en las tiradas de salvación de Inteligencia, Sabiduría y Carisma contra la magia."},{"name":"Lanzamiento de conjuros innato","desc":"La aptitud mágica innata del gnomo es Inteligencia (CD de salvación de conjuros 11). Puede lanzar los siguientes conjuros sin necesidad de componentes materiales:\nA voluntad: indetectable (solo sobre sí mismo)\n1/día cada uno: ceguera/sordera, desenfocar, disfrazarse"},{"name":"Camuflaje pétreo","desc":"El gnomo tiene ventaja en las pruebas de Destreza (Sigilo) para esconderse en terreno rocoso."}],"actions":[],"reactions":[],"legendary":[]}},"srd:deer":{"pt-BR":{"lines":[{"label":"Deslocamento","text":"50 ft"},{"label":"Sentidos","text":"Percepção passiva 12"}],"traits":[],"actions":[],"reactions":[],"legendary":[]},"en":{"lines":[{"label":"Speed","text":"50 ft"},{"label":"Senses","text":"passive Perception 12"}],"traits":[],"actions":[],"reactions":[],"legendary":[]},"es":{"lines":[{"label":"Velocidad","text":"50 ft"},{"label":"Sentidos","text":"Percepción pasiva 12"}],"traits":[],"actions":[],"reactions":[],"legendary":[]}},"srd:deva":{"pt-BR":{"lines":[{"label":"Deslocamento","text":"30 ft, voo 90 ft"},{"label":"Testes de resistência","text":"SAB +9, CAR +9"},{"label":"Perícias","text":"Intuição +9, Percepção +9"},{"label":"Resistência a dano","text":"radiante; concussão, perfurante e cortante de ataques não mágicos"},{"label":"Imunidade a condição","text":"enfeitiçado, exaustão, amedrontado"},{"label":"Sentidos","text":"visão no escuro 120 ft, Percepção passiva 19"},{"label":"Idiomas","text":"todos, telepatia 120 ft"}],"traits":[{"name":"Armas Angelicais","desc":"Os ataques com arma do deva são mágicos. Quando o deva acerta com qualquer arma, ela causa 4d8 de dano radiante extra (já incluído no ataque)."},{"name":"Conjuração Inata","desc":"A habilidade de conjuração do deva é Carisma (CD de resistência de magia 17). O deva pode conjurar as seguintes magias de forma inata, precisando só de componentes verbais:\nÀ vontade: detectar o bem e o mal\n1/dia cada: comunhão, reviver os mortos"},{"name":"Resistência à Magia","desc":"O deva tem vantagem em testes de resistência contra magias e outros efeitos mágicos."}],"actions":[{"name":"Ataques Múltiplos","desc":"O deva faz dois ataques corpo a corpo."},{"name":"Toque Curativo (3/dia)","desc":"O deva toca outra criatura. O alvo recupera magicamente 20 (4d8 + 2) pontos de vida e se livra de qualquer maldição, doença, veneno, cegueira ou surdez."},{"name":"Mudar de Forma","desc":"O deva se metamorfoseia magicamente num humanoide ou fera com nível de desafio igual ou menor que o seu, ou volta à forma verdadeira. Volta à forma verdadeira se morrer. O equipamento que veste ou carrega é absorvido ou levado pela nova forma (à sua escolha).\nNa nova forma, mantém suas estatísticas de jogo e a capacidade de falar, mas a CA, os modos de deslocamento, Força, Destreza e os sentidos especiais são substituídos pelos da nova forma, e ganha as estatísticas e capacidades (exceto características de classe, ações lendárias e ações de covil) que a nova forma tem e que lhe faltam."}],"reactions":[],"legendary":[]},"en":{"lines":[{"label":"Speed","text":"30 ft, fly 90 ft"},{"label":"Saving Throws","text":"Wis +9, Cha +9"},{"label":"Skills","text":"Insight +9, Perception +9"},{"label":"Damage Resistances","text":"radiant; bludgeoning, piercing, and slashing from nonmagical attacks"},{"label":"Condition Immunities","text":"charmed, exhaustion, frightened"},{"label":"Senses","text":"darkvision 120 ft, passive Perception 19"},{"label":"Languages","text":"all, telepathy 120 ft."}],"traits":[{"name":"Angelic Weapons","desc":"The deva's weapon attacks are magical. When the deva hits with any weapon, the weapon deals an extra 4d8 radiant damage (included in the attack)."},{"name":"Innate Spellcasting","desc":"The deva's spellcasting ability is Charisma (spell save DC 17). The deva can innately cast the following spells, requiring only verbal components:\nAt will: detect evil and good\n1/day each: commune, raise dead"},{"name":"Magic Resistance","desc":"The deva has advantage on saving throws against spells and other magical effects."}],"actions":[{"name":"Multiattack","desc":"The deva makes two melee attacks."},{"name":"Healing Touch (3/Day)","desc":"The deva touches another creature. The target magically regains 20 (4d8 + 2) hit points and is freed from any curse, disease, poison, blindness, or deafness."},{"name":"Change Shape","desc":"The deva magically polymorphs into a humanoid or beast that has a challenge rating equal to or less than its own, or back into its true form. It reverts to its true form if it dies. Any equipment it is wearing or carrying is absorbed or borne by the new form (the deva's choice).\nIn a new form, the deva retains its game statistics and ability to speak, but its AC, movement modes, Strength, Dexterity, and special senses are replaced by those of the new form, and it gains any statistics and capabilities (except class features, legendary actions, and lair actions) that the new form has but that it lacks."}],"reactions":[],"legendary":[]},"es":{"lines":[{"label":"Velocidad","text":"30 ft, volar 90 ft"},{"label":"Tiradas de salvación","text":"SAB +9, CAR +9"},{"label":"Habilidades","text":"Perspicacia +9, Percepción +9"},{"label":"Resistencias al daño","text":"radiante; contundente, perforante y cortante de ataques no mágicos"},{"label":"Inmunidades a estados","text":"hechizado, agotamiento, asustado"},{"label":"Sentidos","text":"visión en la oscuridad 120 ft, Percepción pasiva 19"},{"label":"Idiomas","text":"todos, telepatía 120 ft"}],"traits":[{"name":"Armas angelicales","desc":"Los ataques con arma del deva son mágicos. Cuando el deva impacta con cualquier arma, esta inflige 4d8 de daño radiante adicional (incluido en el ataque)."},{"name":"Lanzamiento de conjuros innato","desc":"La aptitud mágica del deva es Carisma (CD de salvación de conjuros 17). El deva puede lanzar de forma innata los siguientes conjuros, necesitando solo componentes verbales:\nA voluntad: detectar el bien y el mal\n1/día cada uno: comunión, revivir a los muertos"},{"name":"Resistencia mágica","desc":"El deva tiene ventaja en las tiradas de salvación contra conjuros y otros efectos mágicos."}],"actions":[{"name":"Ataque múltiple","desc":"El deva hace dos ataques cuerpo a cuerpo."},{"name":"Toque sanador (3/día)","desc":"El deva toca a otra criatura. El objetivo recupera mágicamente 20 (4d8 + 2) puntos de golpe y se libra de cualquier maldición, enfermedad, veneno, ceguera o sordera."},{"name":"Cambiar de forma","desc":"El deva se polimorfa mágicamente en un humanoide o bestia con un valor de desafío igual o inferior al suyo, o vuelve a su forma verdadera. Vuelve a su forma verdadera si muere. El equipo que lleve puesto o encima es absorbido o portado por la nueva forma (a su elección).\nEn la nueva forma conserva sus estadísticas de juego y la capacidad de hablar, pero su CA, sus modos de movimiento, Fuerza, Destreza y sus sentidos especiales se sustituyen por los de la nueva forma, y obtiene las estadísticas y capacidades (salvo rasgos de clase, acciones legendarias y acciones de guarida) que la nueva forma tenga y a él le falten."}],"reactions":[],"legendary":[]}},"srd:dire-wolf":{"pt-BR":{"lines":[{"label":"Deslocamento","text":"50 ft"},{"label":"Perícias","text":"Percepção +3, Furtividade +4"},{"label":"Sentidos","text":"Percepção passiva 13"}],"traits":[{"name":"Audição e Olfato Aguçados","desc":"O lobo tem vantagem em testes de Sabedoria (Percepção) que dependam da audição ou do olfato."},{"name":"Táticas de Matilha","desc":"O lobo tem vantagem nas jogadas de ataque contra uma criatura se ao menos um aliado do lobo estiver a até 5 ft dela e não estiver incapacitado."}],"actions":[],"reactions":[],"legendary":[]},"en":{"lines":[{"label":"Speed","text":"50 ft"},{"label":"Skills","text":"Perception +3, Stealth +4"},{"label":"Senses","text":"passive Perception 13"}],"traits":[{"name":"Keen Hearing and Smell","desc":"The wolf has advantage on Wisdom (Perception) checks that rely on hearing or smell."},{"name":"Pack Tactics","desc":"The wolf has advantage on an attack roll against a creature if at least one of the wolf's allies is within 5 ft. of the creature and the ally isn't incapacitated."}],"actions":[],"reactions":[],"legendary":[]},"es":{"lines":[{"label":"Velocidad","text":"50 ft"},{"label":"Habilidades","text":"Percepción +3, Sigilo +4"},{"label":"Sentidos","text":"Percepción pasiva 13"}],"traits":[{"name":"Oído y olfato agudos","desc":"El lobo tiene ventaja en las pruebas de Sabiduría (Percepción) que dependan del oído o del olfato."},{"name":"Tácticas de manada","desc":"El lobo tiene ventaja en las tiradas de ataque contra una criatura si al menos un aliado del lobo está a 5 ft o menos de ella y no está incapacitado."}],"actions":[],"reactions":[],"legendary":[]}},"srd:djinni":{"pt-BR":{"lines":[{"label":"Deslocamento","text":"30 ft, voo 90 ft"},{"label":"Testes de resistência","text":"DES +6, SAB +7, CAR +9"},{"label":"Imunidade a dano","text":"elétrico, trovejante"},{"label":"Sentidos","text":"visão no escuro 120 ft, Percepção passiva 13"},{"label":"Idiomas","text":"Auran"}],"traits":[{"name":"Fim Elemental","desc":"Se o djinni morrer, seu corpo se desfaz numa brisa morna, deixando para trás só o equipamento que vestia ou carregava."},{"name":"Conjuração Inata","desc":"A habilidade de conjuração inata do djinni é Carisma (CD de resistência de magia 17, +9 para acertar com ataques de magia). Ele pode conjurar as seguintes magias, sem precisar de componentes materiais:\n\nÀ vontade: detectar o bem e o mal, detectar magia, onda trovejante\n3/dia cada: criar alimentos e água (pode criar vinho no lugar da água), idiomas, caminhar no vento\n1/dia cada: conjurar elemental (só elemental do ar), criação, forma gasosa, invisibilidade, imagem maior, viagem planar"}],"actions":[{"name":"Ataques Múltiplos","desc":"O djinni faz três ataques de cimitarra."},{"name":"Criar Redemoinho","desc":"Um cilindro de ar girando, com 5 ft de raio e 30 ft de altura, se forma magicamente num ponto que o djinni possa ver a até 120 ft. O redemoinho dura enquanto o djinni mantiver a concentração (como se concentrasse numa magia). Qualquer criatura, exceto o djinni, que entre no redemoinho deve passar num teste de resistência de Força CD 18 ou fica impedida por ele. O djinni pode mover o redemoinho até 60 ft como ação, e as criaturas impedidas se movem junto. O redemoinho acaba se o djinni o perder de vista.\nUma criatura pode usar a ação para libertar uma criatura impedida pelo redemoinho, inclusive ela mesma, passando num teste de Força CD 18. Se passar, a criatura deixa de estar impedida e vai para o espaço mais próximo fora do redemoinho."}],"reactions":[],"legendary":[]},"en":{"lines":[{"label":"Speed","text":"30 ft, fly 90 ft"},{"label":"Saving Throws","text":"Dex +6, Wis +7, Cha +9"},{"label":"Damage Immunities","text":"lightning, thunder"},{"label":"Senses","text":"darkvision 120 ft, passive Perception 13"},{"label":"Languages","text":"Auran"}],"traits":[{"name":"Elemental Demise","desc":"If the djinni dies, its body disintegrates into a warm breeze, leaving behind only equipment the djinni was wearing or carrying."},{"name":"Innate Spellcasting","desc":"The djinni's innate spellcasting ability is Charisma (spell save DC 17, +9 to hit with spell attacks). It can innately cast the following spells, requiring no material components:\n\nAt will: detect evil and good, detect magic, thunderwave\n3/day each: create food and water (can create wine instead of water), tongues, wind walk\n1/day each: conjure elemental (air elemental only), creation, gaseous form, invisibility, major image, plane shift"}],"actions":[{"name":"Multiattack","desc":"The djinni makes three scimitar attacks."},{"name":"Create Whirlwind","desc":"A 5-foot-radius, 30-foot-tall cylinder of swirling air magically forms on a point the djinni can see within 120 feet of it. The whirlwind lasts as long as the djinni maintains concentration (as if concentrating on a spell). Any creature but the djinni that enters the whirlwind must succeed on a DC 18 Strength saving throw or be restrained by it. The djinni can move the whirlwind up to 60 feet as an action, and creatures restrained by the whirlwind move with it. The whirlwind ends if the djinni loses sight of it.\nA creature can use its action to free a creature restrained by the whirlwind, including itself, by succeeding on a DC 18 Strength check. If the check succeeds, the creature is no longer restrained and moves to the nearest space outside the whirlwind."}],"reactions":[],"legendary":[]},"es":{"lines":[{"label":"Velocidad","text":"30 ft, volar 90 ft"},{"label":"Tiradas de salvación","text":"DES +6, SAB +7, CAR +9"},{"label":"Inmunidades al daño","text":"relámpago, trueno"},{"label":"Sentidos","text":"visión en la oscuridad 120 ft, Percepción pasiva 13"},{"label":"Idiomas","text":"Aurano"}],"traits":[{"name":"Desaparición elemental","desc":"Si el djinni muere, su cuerpo se deshace en una brisa cálida y deja atrás solo el equipo que llevaba puesto o encima."},{"name":"Lanzamiento de conjuros innato","desc":"La aptitud mágica innata del djinni es Carisma (CD de salvación de conjuros 17, +9 al ataque con conjuros). Puede lanzar los siguientes conjuros sin necesidad de componentes materiales:\n\nA voluntad: detectar el bien y el mal, detectar magia, onda atronadora\n3/día cada uno: crear comida y agua (puede crear vino en lugar de agua), don de lenguas, caminar con el viento\n1/día cada uno: conjurar elemental (solo elemental de aire), creación, forma gaseosa, invisibilidad, imagen mayor, desplazamiento entre planos"}],"actions":[{"name":"Ataque múltiple","desc":"El djinni hace tres ataques de cimitarra."},{"name":"Crear torbellino","desc":"Un cilindro de aire arremolinado de 5 ft de radio y 30 ft de alto se forma mágicamente en un punto que el djinni pueda ver a 120 ft o menos. El torbellino dura mientras el djinni mantenga la concentración (como si se concentrara en un conjuro). Cualquier criatura, salvo el djinni, que entre en el torbellino debe superar una tirada de salvación de Fuerza CD 18 o queda apresada por él. El djinni puede mover el torbellino hasta 60 ft como acción, y las criaturas apresadas se mueven con él. El torbellino termina si el djinni lo pierde de vista.\nUna criatura puede usar su acción para liberar a una criatura apresada por el torbellino, incluida ella misma, superando una prueba de Fuerza CD 18. Si la supera, la criatura deja de estar apresada y va al espacio más cercano fuera del torbellino."}],"reactions":[],"legendary":[]}},"srd:donkey":{"pt-BR":{"lines":[{"label":"Deslocamento","text":"0 ft"},{"label":"Testes de resistência","text":"FOR +0, DES +0, CON +0, INT +0, SAB +0, CAR +0"},{"label":"Perícias","text":"Acrobacia +0, Lidar com Animais +0, Arcanismo +0, Atletismo +0, Enganação +0, História +0, Intuição +0, Intimidação +0, Investigação +0, Medicina +0, Natureza +0, Percepção +0, Atuação +0, Persuasão +0, Religião +0, Prestidigitação +0, Furtividade +0, Sobrevivência +0"},{"label":"Sentidos","text":"Percepção passiva 10"}],"traits":[],"actions":[],"reactions":[],"legendary":[]},"en":{"lines":[{"label":"Speed","text":"0 ft"},{"label":"Saving Throws","text":"Str +0, Dex +0, Con +0, Int +0, Wis +0, Cha +0"},{"label":"Skills","text":"Acrobatics +0, Animal Handling +0, Arcana +0, Athletics +0, Deception +0, History +0, Insight +0, Intimidation +0, Investigation +0, Medicine +0, Nature +0, Perception +0, Performance +0, Persuasion +0, Religion +0, Sleight of Hand +0, Stealth +0, Survival +0"},{"label":"Senses","text":"passive Perception 10"}],"traits":[],"actions":[],"reactions":[],"legendary":[]},"es":{"lines":[{"label":"Velocidad","text":"0 ft"},{"label":"Tiradas de salvación","text":"FUE +0, DES +0, CON +0, INT +0, SAB +0, CAR +0"},{"label":"Habilidades","text":"Acrobacias +0, Trato con animales +0, Conocimiento arcano +0, Atletismo +0, Engaño +0, Historia +0, Perspicacia +0, Intimidación +0, Investigación +0, Medicina +0, Naturaleza +0, Percepción +0, Interpretación +0, Persuasión +0, Religión +0, Juego de manos +0, Sigilo +0, Supervivencia +0"},{"label":"Sentidos","text":"Percepción pasiva 10"}],"traits":[],"actions":[],"reactions":[],"legendary":[]}},"srd:doppelganger":{"pt-BR":{"lines":[{"label":"Deslocamento","text":"30 ft"},{"label":"Perícias","text":"Enganação +6, Intuição +3"},{"label":"Imunidade a condição","text":"enfeitiçado"},{"label":"Sentidos","text":"visão no escuro 60 ft, Percepção passiva 11"},{"label":"Idiomas","text":"Comum"}],"traits":[{"name":"Emboscador","desc":"O doppelganger tem vantagem nas jogadas de ataque contra qualquer criatura que tenha surpreendido."},{"name":"Metamorfo","desc":"O doppelganger pode usar a ação para se metamorfosear num humanoide Pequeno ou Médio que já tenha visto, ou voltar à forma verdadeira. Suas estatísticas, exceto o tamanho, são as mesmas em todas as formas. O equipamento que veste ou carrega não se transforma. Volta à forma verdadeira se morrer."},{"name":"Ataque Surpresa","desc":"Se o doppelganger surpreender uma criatura e a acertar com um ataque na primeira rodada de combate, o alvo sofre 10 (3d6) de dano extra desse ataque."}],"actions":[{"name":"Ataques Múltiplos","desc":"O doppelganger faz dois ataques corpo a corpo."},{"name":"Ler Pensamentos","desc":"O doppelganger lê magicamente os pensamentos superficiais de uma criatura a até 60 ft. O efeito atravessa barreiras, mas é bloqueado por 90 cm de madeira ou terra, 60 cm de pedra, 5 cm de metal ou uma fina lâmina de chumbo. Enquanto o alvo estiver no alcance, o doppelganger pode continuar lendo seus pensamentos, desde que mantenha a concentração (como se concentrasse numa magia). Lendo a mente do alvo, tem vantagem em testes de Sabedoria (Intuição) e de Carisma (Enganação, Intimidação e Persuasão) contra ele."}],"reactions":[],"legendary":[]},"en":{"lines":[{"label":"Speed","text":"30 ft"},{"label":"Skills","text":"Deception +6, Insight +3"},{"label":"Condition Immunities","text":"charmed"},{"label":"Senses","text":"darkvision 60 ft, passive Perception 11"},{"label":"Languages","text":"Common"}],"traits":[{"name":"Ambusher","desc":"The doppelganger has advantage on attack rolls against any creature it has surprised."},{"name":"Shapechanger","desc":"The doppelganger can use its action to polymorph into a Small or Medium humanoid it has seen, or back into its true form. Its statistics, other than its size, are the same in each form. Any equipment it is wearing or carrying isn't transformed. It reverts to its true form if it dies."},{"name":"Surprise Attack","desc":"If the doppelganger surprises a creature and hits it with an attack during the first round of combat, the target takes an extra 10 (3d6) damage from the attack."}],"actions":[{"name":"Multiattack","desc":"The doppelganger makes two melee attacks."},{"name":"Read Thoughts","desc":"The doppelganger magically reads the surface thoughts of one creature within 60 ft. of it. The effect can penetrate barriers, but 3 ft. of wood or dirt, 2 ft. of stone, 2 inches of metal, or a thin sheet of lead blocks it. While the target is in range, the doppelganger can continue reading its thoughts, as long as the doppelganger's concentration isn't broken (as if concentrating on a spell). While reading the target's mind, the doppelganger has advantage on Wisdom (Insight) and Charisma (Deception, Intimidation, and Persuasion) checks against the target."}],"reactions":[],"legendary":[]},"es":{"lines":[{"label":"Velocidad","text":"30 ft"},{"label":"Habilidades","text":"Engaño +6, Perspicacia +3"},{"label":"Inmunidades a estados","text":"hechizado"},{"label":"Sentidos","text":"visión en la oscuridad 60 ft, Percepción pasiva 11"},{"label":"Idiomas","text":"Común"}],"traits":[{"name":"Emboscador","desc":"El doppelganger tiene ventaja en las tiradas de ataque contra cualquier criatura a la que haya sorprendido."},{"name":"Cambiaformas","desc":"El doppelganger puede usar su acción para polimorfarse en un humanoide Pequeño o Mediano que haya visto, o volver a su forma verdadera. Sus estadísticas, salvo el tamaño, son las mismas en todas las formas. El equipo que lleve puesto o encima no se transforma. Vuelve a su forma verdadera si muere."},{"name":"Ataque sorpresa","desc":"Si el doppelganger sorprende a una criatura y la impacta con un ataque durante el primer asalto del combate, el objetivo recibe 10 (3d6) de daño adicional de ese ataque."}],"actions":[{"name":"Ataque múltiple","desc":"El doppelganger hace dos ataques cuerpo a cuerpo."},{"name":"Leer pensamientos","desc":"El doppelganger lee mágicamente los pensamientos superficiales de una criatura a 60 ft o menos. El efecto atraviesa barreras, pero lo bloquean 90 cm de madera o tierra, 60 cm de piedra, 5 cm de metal o una fina lámina de plomo. Mientras el objetivo esté al alcance, puede seguir leyendo sus pensamientos siempre que mantenga la concentración (como si se concentrara en un conjuro). Mientras lee la mente del objetivo, tiene ventaja en las pruebas de Sabiduría (Perspicacia) y de Carisma (Engaño, Intimidación y Persuasión) contra él."}],"reactions":[],"legendary":[]}},"srd:draft-horse":{"pt-BR":{"lines":[{"label":"Deslocamento","text":"40 ft"},{"label":"Testes de resistência","text":"FOR +0, DES +0, CON +0, INT +0, SAB +0, CAR +0"},{"label":"Perícias","text":"Acrobacia +0, Lidar com Animais +0, Arcanismo +0, Atletismo +0, Enganação +0, História +0, Intuição +0, Intimidação +0, Investigação +0, Medicina +0, Natureza +0, Percepção +0, Atuação +0, Persuasão +0, Religião +0, Prestidigitação +0, Furtividade +0, Sobrevivência +0"},{"label":"Sentidos","text":"Percepção passiva 10"}],"traits":[],"actions":[],"reactions":[],"legendary":[]},"en":{"lines":[{"label":"Speed","text":"40 ft"},{"label":"Saving Throws","text":"Str +0, Dex +0, Con +0, Int +0, Wis +0, Cha +0"},{"label":"Skills","text":"Acrobatics +0, Animal Handling +0, Arcana +0, Athletics +0, Deception +0, History +0, Insight +0, Intimidation +0, Investigation +0, Medicine +0, Nature +0, Perception +0, Performance +0, Persuasion +0, Religion +0, Sleight of Hand +0, Stealth +0, Survival +0"},{"label":"Senses","text":"passive Perception 10"}],"traits":[],"actions":[],"reactions":[],"legendary":[]},"es":{"lines":[{"label":"Velocidad","text":"40 ft"},{"label":"Tiradas de salvación","text":"FUE +0, DES +0, CON +0, INT +0, SAB +0, CAR +0"},{"label":"Habilidades","text":"Acrobacias +0, Trato con animales +0, Conocimiento arcano +0, Atletismo +0, Engaño +0, Historia +0, Perspicacia +0, Intimidación +0, Investigación +0, Medicina +0, Naturaleza +0, Percepción +0, Interpretación +0, Persuasión +0, Religión +0, Juego de manos +0, Sigilo +0, Supervivencia +0"},{"label":"Sentidos","text":"Percepción pasiva 10"}],"traits":[],"actions":[],"reactions":[],"legendary":[]}}};
